    : SIMULATIONS.find(p => p.id === activeProfileId) || SIMULATIONS[0];

  const scrollToBottom = () => messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  useEffect(() => scrollToBottom(), [messages]);

  // Audio setup
  useEffect(() => {
    if (typeof window !== "undefined") {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (SpeechRecognition) {
        const recognition = new SpeechRecognition();
        recognition.continuous = false;
        recognition.interimResults = true;
        recognition.lang = "en-US";
        recognition.onresult = (e: any) => {
           const t = Array.from(e.results).map((r: any) => r[0].transcript).join("");
           setInputValue(t);
        };
        recognition.onend = () => setIsListening(false);
        recognitionRef.current = recognition;
      }
    }
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) return setToast({ msg: "Voice input not supported", type: "error" });
    if (isListening) recognitionRef.current.stop();
    else {
        recognitionRef.current.start();
        setIsListening(true);
    }
  };

  const selectProfile = (profile: Profile, newMode: AppMode) => {
      setMode(newMode);
      setActiveProfileId(profile.id);
      setMessages([]);
      setView('chat');

      // Auto-start simulation logic
      if (newMode === 'simulation' && profile.startPrompt) {
          startSimulation(profile);
      }
  };

  const startSimulation = async (profile: Profile) => {
      setIsLoading(true);
      const startTime = Date.now();
      setMessages([{ role: "model", text: "", timestamp: startTime }]);

      try {
         await new Promise(r => setTimeout(r, 800));
         setMessages([{ role: "model", text: profile.startPrompt || "", timestamp: Date.now(), latency: 45 }]);
      } finally {
         setIsLoading(false);
      }
  };

  const handleSend = async () => {
    if (!inputValue.trim() || isLoading) return;
    const userMsg = inputValue;
    setInputValue("");
    setMessages(prev => [...prev, { role: "user", text: userMsg, timestamp: Date.now() }]);
    setIsLoading(true);

    const startTime = Date.now();
    let firstTokenTime = 0;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

      if (isImageGenEnabled) {
          // --- IMAGE GENERATION MODE (IMAGEN 3) ---
          const response = await ai.models.generateImages({
            model: 'imagen-3.0-generate-001',
            prompt: userMsg,
            config: {
                numberOfImages: 1,
                aspectRatio: '16:9',
            },
          });

          const base64 = response.generatedImages?.[0]?.image?.imageBytes;
          if (base64) {
             const imageUrl = `data:image/jpeg;base64,${base64}`;
             setMessages(prev => [...prev, { 
                 role: "model", 
                 text: `Generated visual for: "${userMsg}"`, 
                 image: imageUrl,
                 timestamp: Date.now(),
                 latency: Date.now() - startTime
             }]);
          } else {
             throw new Error("No image generated");
          }

      } else {
          // --- STANDARD CHAT MODE (GEMINI 3) ---
          const history = messages.map(m => ({ role: m.role, parts: [{ text: m.text }] }));

          // Construct System Instruction with RAG
          let sysInstruction = activeProfile.instruction;
          if (customKnowledge.trim()) {
              sysInstruction += `\n\n[CORE KNOWLEDGE BASE]\nThe user has provided the following specific knowledge context. Use it to answer questions if relevant:\n\n${customKnowledge}\n\n[END KNOWLEDGE BASE]`;
          }

          // Configure Tools (Search)
          const tools: Tool[] = [];
          if (isWebSearchEnabled) {
              tools.push({ googleSearch: {} });
          }

          // Thinking Config
          const config: any = {
            systemInstruction: sysInstruction,
            tools: tools,
          };

          if (isThinkingEnabled) {
              config.thinkingConfig = { thinkingBudget: 32768 };
          }

          const chat = ai.chats.create({
            model: "gemini-3-pro-preview", 
            config: config,
            history: history 
          });

          setMessages(prev => [...prev, { role: "model", text: "", timestamp: Date.now() }]);

          const result = await chat.sendMessageStream({ message: userMsg });

          let fullResponse = "";
          let groundingMetadata: GroundingMetadata | null = null;

          for await (const chunk of result) {
            if (!firstTokenTime) firstTokenTime = Date.now();
            fullResponse += chunk.text;

            // Capture grounding metadata if present in any chunk
            if (chunk.candidates?.[0]?.groundingMetadata) {
                groundingMetadata = chunk.candidates[0].groundingMetadata;
            }

            setMessages(prev => {
              const updated = [...prev];
              const last = updated[updated.length - 1];
              if (last.role === "model") {
                  last.text = fullResponse;
                  // Update metadata if found
                  if (groundingMetadata) last.groundingMetadata = groundingMetadata;
              }
              return updated;
            });
          }

          const latency = firstTokenTime - startTime;
          setMessages(prev => {
              const updated = [...prev];
              updated[updated.length - 1].latency = latency;
              return updated;
          });
      }

      setStats(prev => ({
          ...prev,
          totalMessages: prev.totalMessages + 1,
          lastLatency: Date.now() - startTime
      }));

    } catch (error: any) {
      console.error(error);
      setMessages(prev => [...prev, { role: "model", text: "Connection failure or generation error.", isError: true, timestamp: Date.now() }]);
      setToast({ msg: "Failed to generate response.", type: 'error' });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen w-full font-sans text-gray-100 overflow-hidden relative selection:bg-cyan-500/30 selection:text-cyan-100">

      {toast && <Toast message={toast.msg} type={toast.type} onClose={() => setToast(null)} />}
      <KPIBoard stats={stats} />
      <KnowledgeModal isOpen={isKnowledgeOpen} onClose={() => setIsKnowledgeOpen(false)} value={customKnowledge} onChange={setCustomKnowledge} />

      {/* Sidebar */}
      <aside className="hidden md:flex flex-col w-72 glass-panel border-r border-white/5 z-20 shrink-0 h-full">
        {/* Header */}
        <div className="p-6 pb-4">
            <div className="flex items-center gap-3 mb-6 cursor-pointer hover:opacity-80 transition-opacity" onClick={() => setView('home')}>
                <div className={`w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center shadow-lg shadow-indigo-500/20`}>
                    <span className="text-white font-bold text-xl">G3</span>
                </div>
                <div>
                    <h1 className="font-bold text-lg tracking-tight text-white leading-none">Gemini 3.0</h1>
                    <p className="text-[10px] text-gray-400 font-mono tracking-widest uppercase mt-1">Enterprise Edition</p>
                </div>
            </div>

            {/* Dashboard Nav */}
            <button 
                onClick={() => setView('home')}
                className={`w-full flex items-center gap-3 px-3 py-3 mb-6 rounded-xl transition-all ${view === 'home' ? 'bg-white/10 text-white font-medium' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
            >
                <Icons.Home />
                <span>Dashboard</span>
            </button>

            {view === 'chat' && (
                <>
                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3 px-1 flex items-center gap-2">
                        {mode === 'assistant' ? <><Icons.Plugin /> Active Protocol</> : <><Icons.Sim /> Client Persona</>}
                    </h3>

                    <div className="space-y-1 mb-6">
                        {(mode === 'assistant' ? ASSISTANTS : SIMULATIONS).map(p => (
                            <button
                                key={p.id}
                                onClick={() => selectProfile(p, mode)}
                                className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl text-left transition-all duration-200 border group
                                ${activeProfileId === p.id 
                                    ? "bg-white/10 border-white/10 text-white shadow-lg" 
                                    : "border-transparent text-gray-400 hover:text-gray-200 hover:bg-white/5"}`}
                            >
                                <div className={`w-8 h-8 rounded-lg flex items-center justify-center transition-colors ${activeProfileId === p.id ? 'bg-white/10 text-white' : 'bg-black/20 text-gray-500 group-hover:text-gray-300'}`}>
                                    {p.icon}
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="font-medium text-sm truncate">{p.name}</div>
                                </div>
                                {activeProfileId === p.id && <div className={`w-1.5 h-1.5 rounded-full shadow-[0_0_8px_currentColor] ${mode === 'simulation' ? 'bg-amber-400' : 'bg-cyan-400'}`}></div>}
                            </button>
                        ))}
                    </div>
                </>
            )}

            {/* Knowledge Section */}
            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3 px-1 flex items-center gap-2">
                <Icons.Database /> Knowledge Core
            </h3>
            <div className="space-y-2">
                <button 
                    onClick={() => setIsKnowledgeOpen(true)}
                    className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl border transition-all ${customKnowledge ? 'bg-indigo-500/20 border-indigo-500/40 text-indigo-100' : 'bg-black/20 border-white/5 text-gray-400 hover:bg-white/5 hover:text-white'}`}
                >
                    <div className="w-8 h-8 rounded-lg bg-black/30 flex items-center justify-center">
                        <Icons.Database />
                    </div>
                    <div className="flex-1 text-left">
                        <div className="text-xs font-medium">Neural Link</div>
                        <div className="text-[10px] opacity-60">{customKnowledge ? 'Connected' : 'Configure R.A.G.'}</div>
                    </div>
                    {customKnowledge && <div className="w-1.5 h-1.5 rounded-full bg-indigo-400 shadow-[0_0_5px_currentColor]"></div>}
                </button>

                <button 
                    onClick={() => {
                        setIsWebSearchEnabled(!isWebSearchEnabled);
                        if (!isWebSearchEnabled) setIsImageGenEnabled(false);
                    }}
                    className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl border transition-all ${isWebSearchEnabled ? 'bg-cyan-500/20 border-cyan-500/40 text-cyan-100' : 'bg-black/20 border-white/5 text-gray-400 hover:bg-white/5 hover:text-white'}`}
                >
                    <div className="w-8 h-8 rounded-lg bg-black/30 flex items-center justify-center">
                        <Icons.Web />
                    </div>
                    <div className="flex-1 text-left">
                        <div className="text-xs font-medium">Net Access</div>
                        <div className="text-[10px] opacity-60">{isWebSearchEnabled ? 'Grounding On' : 'Grounding Off'}</div>
                    </div>
                    <div className={`w-8 h-4 rounded-full p-0.5 transition-colors ${isWebSearchEnabled ? 'bg-cyan-500' : 'bg-gray-700'}`}>
                        <div className={`w-3 h-3 bg-white rounded-full shadow-sm transition-transform ${isWebSearchEnabled ? 'translate-x-4' : 'translate-x-0'}`}></div>
                    </div>
                </button>

                <button 
                    onClick={() => {
                        setIsThinkingEnabled(!isThinkingEnabled);
                        if (!isThinkingEnabled) setIsImageGenEnabled(false);
                    }}
                    className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl border transition-all ${isThinkingEnabled ? 'bg-purple-500/20 border-purple-500/40 text-purple-100' : 'bg-black/20 border-white/5 text-gray-400 hover:bg-white/5 hover:text-white'}`}
                >
                    <div className="w-8 h-8 rounded-lg bg-black/30 flex items-center justify-center">
                        <Icons.Brain />
                    </div>
                    <div className="flex-1 text-left">
                        <div className="text-xs font-medium">Thinking Mode</div>
                        <div className="text-[10px] opacity-60">{isThinkingEnabled ? 'Deep Reason (32k)' : 'Standard'}</div>
                    </div>
                    <div className={`w-8 h-4 rounded-full p-0.5 transition-colors ${isThinkingEnabled ? 'bg-purple-500' : 'bg-gray-700'}`}>
                        <div className={`w-3 h-3 bg-white rounded-full shadow-sm transition-transform ${isThinkingEnabled ? 'translate-x-4' : 'translate-x-0'}`}></div>
                    </div>
                </button>

                <button 
                    onClick={() => {
                        setIsImageGenEnabled(!isImageGenEnabled);
                        if (!isImageGenEnabled) {
                            setIsWebSearchEnabled(false);
                            setIsThinkingEnabled(false);
                        }
                    }}
                    className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl border transition-all ${isImageGenEnabled ? 'bg-pink-500/20 border-pink-500/40 text-pink-100' : 'bg-black/20 border-white/5 text-gray-400 hover:bg-white/5 hover:text-white'}`}
                >
                    <div className="w-8 h-8 rounded-lg bg-black/30 flex items-center justify-center">
                        <Icons.Image />
                    </div>
                    <div className="flex-1 text-left">
                        <div className="text-xs font-medium">Image Gen</div>
                        <div className="text-[10px] opacity-60">{isImageGenEnabled ? 'Imagen 3 Active' : 'Off'}</div>
                    </div>
                    <div className={`w-8 h-4 rounded-full p-0.5 transition-colors ${isImageGenEnabled ? 'bg-pink-500' : 'bg-gray-700'}`}>
                        <div className={`w-3 h-3 bg-white rounded-full shadow-sm transition-transform ${isImageGenEnabled ? 'translate-x-4' : 'translate-x-0'}`}></div>
                    </div>
                </button>
            </div>
        </div>

        <div className="mt-auto p-4 border-t border-white/5 bg-black/20">
             <div className="flex justify-between items-center mb-2">
                <span className="text-[10px] text-gray-500 font-mono">SERVER STATUS</span>
                <span className="text-[10px] text-emerald-400 flex items-center gap-1">
                    <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                    ONLINE
                </span>
             </div>
        </div>
      </aside>

      {/* Main Area */}
      <main className="flex-1 flex flex-col relative z-10 h-full">
        {/* Mobile Header */}
        <header className="md:hidden h-14 glass-panel border-b border-white/5 flex items-center px-4 justify-between shrink-0">
             <span className="font-bold">Gemini 3.0</span>
             <div className="flex gap-2">
                 <button onClick={() => setView('home')} className="text-xs px-3 py-1 bg-white/10 rounded-full border border-white/10">
                    Home
                 </button>
             </div>
        </header>

        {view === 'home' ? (
            <HomeScreen onSelectProfile={selectProfile} />
        ) : (
            <>
                {/* Chat Feed */}
                <div className="flex-1 overflow-y-auto p-4 md:p-8 w-full max-w-4xl mx-auto scroll-smooth">
                {messages.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-center opacity-0 animate-slide-up">
                    <div className={`w-40 h-40 rounded-full bg-gradient-to-br ${activeProfile.color} blur-[60px] absolute opacity-20`}></div>
                    <div className="relative z-10 p-8 glass-panel rounded-3xl border border-white/10 mb-8 max-w-md">
                        <div className="w-16 h-16 mx-auto mb-4 text-white bg-white/5 rounded-2xl flex items-center justify-center border border-white/10 shadow-inner">
                            {activeProfile.icon}
                        </div>
                        <h2 className="text-2xl font-bold mb-2 text-white">{activeProfile.name}</h2>
                        <p className="text-gray-400 text-sm leading-relaxed mb-6">
                        {activeProfile.instruction}
                        </p>
                        {mode === 'simulation' && (
                            <button onClick={() => startSimulation(activeProfile)} className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-white rounded-full text-sm font-medium transition-colors shadow-lg shadow-amber-900/20">
                                Restart Simulation
                            </button>
                        )}
                        {mode === 'assistant' && !customKnowledge && (
                            <button onClick={() => setIsKnowledgeOpen(true)} className="px-6 py-2 bg-indigo-600/50 hover:bg-indigo-600 text-white rounded-full text-sm font-medium transition-colors shadow-lg border border-indigo-500/30">
                                <span className="flex items-center gap-2"><Icons.Database /> Connect Data</span>
                            </button>
                        )}
                    </div>
                    </div>
                ) : (
                    <div className="flex flex-col gap-2 pb-6">
                        {messages.map((msg, idx) => (
                            <MessageBubble 
                                key={idx} 
                                {...msg} 
                                showAvatar={idx === 0 || messages[idx-1].role !== msg.role}
                                mode={mode}
                            />
                        ))}
                        {isLoading && messages[messages.length - 1]?.text === "" && (
                            <div className="flex w-full mb-6 justify-start pl-14">
                                <div className="px-4 py-3 rounded-2xl glass-panel-light flex items-center gap-1.5 h-10">
                                    <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce"></div>
                                    <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce delay-100"></div>
                                    <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce delay-200"></div>
                                </div>
                            </div>
                        )}
                    </div>
                )}
                <div ref={messagesEndRef} className="h-4" />
                </div>

                {/* Input Bar */}
                <footer className="shrink-0 p-4 md:p-6 pt-0">
                <div className="max-w-4xl mx-auto relative group">
                    <div className={`absolute -inset-0.5 bg-gradient-to-r rounded-2xl blur opacity-20 group-hover:opacity-30 transition duration-1000 ${activeProfile.color}`}></div>

                    <div className="relative flex items-end gap-2 glass-panel p-2 rounded-2xl shadow-2xl">
                        <button
                            onClick={toggleListening}
                            className={`p-3 rounded-xl shrink-0 transition-all ${isListening ? "bg-red-500/20 text-red-400" : "text-gray-400 hover:text-white hover:bg-white/5"}`}
                        >
                            <Icons.Mic active={isListening} />
                        </button>

                        <textarea
                            className="w-full bg-transparent text-gray-100 placeholder-gray-500/50 text-base p-2.5 max-h-32 min-h-[48px] outline-none resize-none font-medium"
                            placeholder={isListening ? "Listening..." : mode === 'simulation' ? `Reply to ${activeProfile.name}...` : `Ask ${activeProfile.name}...`}
                            rows={1}
                            value={inputValue}
                            onChange={(e) => setInputValue(e.target.value)}
                            onKeyDown={(e) => {
                                if (e.key === "Enter" && !e.shiftKey) {
                                    e.preventDefault();
                                    handleSend();
                                }
                            }}
                        />

                        <button
                            onClick={handleSend}
                            disabled={isLoading}
                            className={`p-3 rounded-xl shrink-0 transition-all duration-300 ${
                                !inputValue.trim() 
                                ? "bg-white/5 text-gray-600" 
                                : "bg-white text-black hover:bg-gray-200 shadow-lg hover:scale-105"
                            }`}
                        >
                            {isLoading ? <Icons.Stop /> : <Icons.Send />}
                        </button>
                    </div>

                    <div className="flex justify-center mt-2 opacity-40 hover:opacity-100 transition-opacity gap-3">
                        <span className="text-[10px] font-mono text-gray-400 bg-black/40 px-2 py-0.5 rounded border border-white/5">
                            GEMINI 3 // {mode.toUpperCase()}
                        </span>
                        {customKnowledge && (
                            <span className="text-[10px] font-mono text-indigo-300 bg-indigo-900/20 px-2 py-0.5 rounded border border-indigo-500/20 flex items-center gap-1">
                                <span className="w-1.5 h-1.5 rounded-full bg-indigo-400 animate-pulse"></span> RAG ACTIVE
                            </span>
                        )}
                        {isWebSearchEnabled && (
                            <span className="text-[10px] font-mono text-cyan-300 bg-cyan-900/20 px-2 py-0.5 rounded border border-cyan-500/20 flex items-center gap-1">
                                <span className="w-1.5 h-1.5 rounded-full bg-cyan-400"></span> NET ACTIVE
                            </span>
                        )}
                        {isThinkingEnabled && (
                            <span className="text-[10px] font-mono text-purple-300 bg-purple-900/20 px-2 py-0.5 rounded border border-purple-500/20 flex items-center gap-1">
                                <span className="w-1.5 h-1.5 rounded-full bg-purple-400"></span> THINKING (32K)
                            </span>
                        )}
                        {isImageGenEnabled && (
                            <span className="text-[10px] font-mono text-pink-300 bg-pink-900/20 px-2 py-0.5 rounded border border-pink-500/20 flex items-center gap-1">
                                <span className="w-1.5 h-1.5 rounded-full bg-pink-400"></span> IMAGEN 3
                            </span>
                        )}
                    </div>
                </div>
                </footer>
            </>
        )}
      </main>
    </div>
  );
};

const root = createRoot(document.getElementById("root")!);
root.render(<App />);

