const KnowledgeModal = ({ isOpen, onClose, value, onChange }: { isOpen: boolean, onClose: () => void, value: string, onChange: (v: string) => void }) => {
    const [url, setUrl] = useState("");
    const [isFetching, setIsFetching] = useState(false);
    const [error, setError] = useState("");

    const handleFetchUrl = async () => {
        if (!url.trim()) return;
        setIsFetching(true);
        setError("");
        try {
            // Attempt to fetch content. 
            // NOTE: CORS will likely block direct browser requests to random sites. 
            // In a production environment, this would go through a proxy.
            const response = await fetch(url);
            if (!response.ok) throw new Error("Failed to fetch. Site might be blocking automated access (CORS).");
            const text = await response.text();

            // Basic HTML stripping if it's a webpage
            const strippedText = text.replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim();

            onChange(value + "\n\n[REMOTE CONTEXT: " + url + "]\n" + strippedText);
            setUrl("");
            onClose();
        } catch (err: any) {
            setError(err.message || "Failed to fetch content.");
        } finally {
            setIsFetching(false);
        }
    };

    if (!isOpen) return null;
    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
            <div className="w-full max-w-2xl glass-panel rounded-2xl flex flex-col max-h-[85vh] animate-slide-up">
                <div className="p-6 border-b border-white/5 flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-indigo-500/20 text-indigo-300 rounded-lg"><Icons.Database /></div>
                        <div>
                            <h3 className="text-lg font-bold text-white">Neural Knowledge Base</h3>
                            <p className="text-xs text-gray-400">Expand AI memory with text or live URLs</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="text-gray-400 hover:text-white">✕</button>
                </div>

                <div className="p-6 flex-1 flex flex-col min-h-0 space-y-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Remote Intelligence URL</label>
                        <div className="flex gap-2">
                            <input 
                                type="url"
                                placeholder="https://example.com/docs"
                                className="flex-1 bg-black/30 border border-white/10 rounded-xl px-4 py-2 text-sm text-gray-300 focus:outline-none focus:border-indigo-500/50"
                                value={url}
                                onChange={(e) => setUrl(e.target.value)}
                            />
                            <button 
                                onClick={handleFetchUrl}
                                disabled={isFetching || !url}
                                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 disabled:bg-gray-700 text-white rounded-xl text-xs font-bold transition-all flex items-center gap-2"
                            >
                                {isFetching ? <Icons.Loader /> : "Link"}
                            </button>
                        </div>
                        {error && <p className="text-[10px] text-red-400 mt-1">{error}</p>}
                    </div>

                    <div className="flex-1 flex flex-col min-h-0">
                        <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-2">Neural Workspace (Raw Context)</label>
                        <textarea 
                            className="flex-1 w-full bg-black/30 border border-white/10 rounded-xl p-4 text-sm font-mono text-gray-300 focus:outline-none focus:border-indigo-500/50 resize-none"
                            placeholder="Paste your document content or NotebookLM export here..."
                            value={value}
                            onChange={(e) => onChange(e.target.value)}
                        />
                    </div>

                    <div className="flex justify-between items-center mt-2">
                        <span className="text-xs text-gray-500">{value.length} neural tokens injected</span>
                        <div className="flex gap-2">
                            <button onClick={() => onChange("")} className="px-4 py-2 text-gray-400 hover:text-white text-xs font-medium">Clear</button>
                            <button onClick={onClose} className="px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg text-sm font-medium transition-colors">
                                Synchronize
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

const MarkdownContent = memo(({ content }: { content: string }) => {
  const parts = content.split(/(```[\s\S]*?```)/g);
  return (
    <div className="prose prose-invert prose-sm max-w-none leading-relaxed">
      {parts.map((part, index) => {
        if (part.startsWith("```")) {
          const match = part.match(/```(\w*)\n([\s\S]*?)```/);
          const lang = match ? match[1] : "";
          const code = match ? match[2] : part.slice(3, -3);
          return (
            <div key={index} className="my-3 overflow-hidden rounded-lg border border-white/10 bg-black/40 backdrop-blur-sm group">
                <div className="flex justify-between items-center bg-white/5 px-3 py-1.5 border-b border-white/5">
                    <span className="text-[10px] text-gray-500 font-mono uppercase tracking-wider">{lang || 'TEXT'}</span>
                    <button onClick={() => copyToClipboard(code)} className="text-gray-500 hover:text-white transition-colors">
                        <Icons.Copy />
                    </button>
                </div>
                <pre className="!bg-transparent !p-4 !m-0 overflow-x-auto text-xs md:text-sm">
                    <code>{code}</code>
                </pre>
            </div>
          );
        }
        return (
          <span key={index} dangerouslySetInnerHTML={{ 
              __html: part.replace(/\*\*(.*?)\*\*/g, '<strong class="text-white font-bold">$1</strong>').replace(/\n/g, '<br/>')
          }} />
        );
      })}
    </div>
  );
});

interface MessageBubbleProps extends Message {
  showAvatar: boolean;
  mode: AppMode;
}

const MessageBubble = memo(({ role, text, image, isError, timestamp, latency, showAvatar, mode, groundingMetadata }: MessageBubbleProps) => {
  const isUser = role === "user";
  const dateStr = new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const citations = groundingMetadata?.groundingChunks?.filter(c => c.web?.uri) || [];

  const bubbleStyle = isUser
    ? "bg-indigo-600/20 border-indigo-500/20 text-white rounded-2xl rounded-tr-sm hover:bg-indigo-600/25"
    : mode === 'simulation'
        ? "bg-amber-900/20 border-amber-500/10 text-amber-100 rounded-2xl rounded-tl-sm hover:border-amber-500/20 shadow-[0_0_15px_rgba(245,158,11,0.05)]"
        : `bg-gray-900/60 border-white/5 text-gray-200 rounded-2xl rounded-tl-sm hover:border-white/15 ${isError ? "border-red-500/40 bg-red-900/10 text-red-200" : ""}`;

  return (
    <div className={`flex w-full mb-4 group ${isUser ? "justify-end" : "justify-start"}`}>
      <div className={`flex max-w-[90%] md:max-w-[75%] gap-3 ${isUser ? "flex-row-reverse" : "flex-row"}`}>
        <div className={`w-9 h-9 shrink-0 flex items-center justify-center rounded-xl backdrop-blur-md border shadow-lg transition-all duration-500
            ${isUser ? 'bg-indigo-500/10 border-indigo-500/20 text-indigo-300 hidden md:flex' : 
              mode === 'simulation' ? 'bg-amber-500/10 border-amber-500/20 text-amber-500' : 'bg-gray-800/60 border-white/10 text-cyan-400'} 
            ${!showAvatar && !isUser ? 'invisible' : ''}`}>
           {isUser ? <Icons.User /> : <Icons.Bot />}
        </div>
        <div className="flex flex-col min-w-0">
            <div className="flex items-center gap-2 mb-1 px-1">
                <span className="text-[10px] font-mono text-gray-500">{isUser ? 'YOU' : mode === 'simulation' ? 'SIMULATION' : 'GEMINI 3'}</span>
                <span className="text-[10px] text-gray-600">{dateStr}</span>
                {!isUser && latency && (
                    <span className="text-[9px] text-gray-700 bg-white/5 px-1 rounded border border-white/5">{latency}ms</span>
                )}
            </div>
            <div className={`px-5 py-4 shadow-xl backdrop-blur-xl border relative transition-all duration-300 ${bubbleStyle}`}>
                {image && (
                    <div className="mb-3 rounded-lg overflow-hidden border border-white/10">
                        <img src={image} alt="Generated Content" className="w-full h-auto" />
                    </div>
                )}
                {text && <MarkdownContent content={text} />}
                {citations.length > 0 && (
                  <div className="mt-4 pt-3 border-t border-white/10">
                    <p className="text-[10px] font-semibold text-gray-400 mb-2 uppercase tracking-wider flex items-center gap-1">
                       <Icons.Link /> Sources
                    </p>
                    <div className="flex flex-wrap gap-2">
                        {citations.map((chunk, i) => (
                            <a 
                                key={i}
                                href={chunk.web?.uri}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="flex items-center gap-1.5 px-2 py-1 bg-black/30 hover:bg-white/10 border border-white/10 rounded text-[10px] text-cyan-300 transition-colors truncate max-w-[200px]"
                            >
                                <span className="truncate">{chunk.web?.title || chunk.web?.uri}</span>
                            </a>
                        ))}
                    </div>
                  </div>
                )}
            </div>
            {!isUser && !isError && text && (
                <div className="flex gap-1 mt-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200 px-1">
                    <button onClick={() => speakText(text)} className="p-1.5 text-gray-500 hover:text-cyan-400 transition-colors rounded-lg hover:bg-white/5">
                        <Icons.Volume />
                    </button>
                    <button onClick={() => copyToClipboard(text)} className="p-1.5 text-gray-500 hover:text-cyan-400 transition-colors rounded-lg hover:bg-white/5">
                        <Icons.Copy />
                    </button>
                </div>
            )}
        </div>
      </div>
    </div>
  );
});

