        <div className={`absolute inset-0 opacity-0 group-hover:opacity-10 transition-opacity bg-gradient-to-br ${profile.color}`} />
        <div className="relative flex items-start gap-4">
            <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 bg-gradient-to-br ${profile.color} shadow-lg`}>
                <span className="text-white text-xl">{profile.icon}</span>
            </div>
            <div>
                <h3 className="text-lg font-bold text-white mb-1">{profile.name}</h3>
                <p className="text-sm text-cyan-200/80 font-mono mb-2">{profile.description}</p>
                <p className="text-xs text-gray-400 line-clamp-2">{profile.instruction}</p>
