// --- TCM Organ Clock Visualizer ---
const TCMOrganClock = memo(() => {
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const currentHour = currentTime.getHours();

  const getActiveOrganIndex = () => {
    const index = ORGAN_CLOCK_DATA.findIndex(o => {
      if (o.startHour > o.endHour) { // Midnight crossing case (Gallbladder 23-1)
        return currentHour >= o.startHour || currentHour < o.endHour;
      }
      return currentHour >= o.startHour && currentHour < o.endHour;
    });
    return index === -1 ? 0 : index;
  };

  const activeIdx = getActiveOrganIndex();
  const activeOrgan = ORGAN_CLOCK_DATA[activeIdx];

  // We rotate the dial so the active organ is at the top (0 degrees)
  // Each segment is 30 degrees (360 / 12)
  // Gallbladder is segment 0, start 23:00. 
  // We offset by activeIdx * 30 to rotate the dial.
  const rotation = -(activeIdx * 30);

  return (
    <div className="flex flex-col items-center justify-center p-4">
      <div className="relative w-56 h-56 rounded-full border border-white/10 flex items-center justify-center bg-black/20 shadow-inner">
        {/* The Dial */}
        <div 
          className="absolute inset-0 transition-transform duration-1000 ease-in-out" 
          style={{ transform: `rotate(${rotation}deg)` }}
        >
          {ORGAN_CLOCK_DATA.map((o, i) => {
            const angle = i * 30;
            return (
              <div 
                key={o.name}
                className="absolute inset-0 flex flex-col items-center pt-2 origin-center"
                style={{ transform: `rotate(${angle}deg)` }}
              >
                <span 
                    className={`text-[9px] font-bold tracking-tighter uppercase transition-colors duration-500 ${i === activeIdx ? 'text-cyan-400 drop-shadow-[0_0_5px_rgba(34,211,238,0.5)]' : 'text-gray-600'}`}
                    style={{ transform: `rotate(${-angle - rotation}deg)` }}
                >
                  {o.name.split(' ')[0]}
                </span>
              </div>
            );
          })}
        </div>

        {/* The Static Hand */}
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-0.5 h-1/2 bg-gradient-to-b from-cyan-400 to-transparent shadow-[0_0_15px_rgba(34,211,238,0.8)] z-10"></div>

        {/* Center Hub */}
        <div className="relative z-20 w-32 h-32 rounded-full glass-panel border border-white/10 flex flex-col items-center justify-center text-center p-2">
            <div className="text-[10px] text-gray-500 font-mono mb-1">{currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div>
            <div className="text-sm font-bold text-cyan-50 leading-tight mb-1">{activeOrgan.name}</div>
            <div className="text-[9px] text-gray-400 leading-tight italic line-clamp-2 px-2">"{activeOrgan.action}"</div>
        </div>
      </div>

      <div className="mt-6 w-full glass-panel-light p-4 rounded-xl border border-white/5">
        <div className="flex items-center gap-2 mb-2">
            <Icons.Time />
            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Biological Guidance</span>
        </div>
        <p className="text-xs text-gray-300 leading-relaxed">
            Current Qi Focus: <span className="text-cyan-400 font-bold">{activeOrgan.name}</span>. 
            TCM wisdom suggests focusing on <span className="text-white underline decoration-cyan-500/30">{activeOrgan.action.toLowerCase()}</span> during this cycle to maintain body harmony.
        </p>
      </div>
    </div>
  );
});

const KnowledgeModal = ({ isOpen, onClose, value, onChange }: { isOpen: boolean, onClose: () => void, value: string, onChange: (v: string) => void }) => {
    const [url, setUrl] = useState("");
    const [isFetching, setIsFetching] = useState(false);
    const [error, setError] = useState("");

    const handleFetchUrl = async () => {
        if (!url.trim()) return;
        setIsFetching(true);
        setError("");
        try {
            const response = await fetch(url);
            if (!response.ok) throw new Error("Failed to fetch. Site might be blocking automated access (CORS).");
            const text = await response.text();
            const strippedText = text.replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim();
            onChange(value + "\n\n[REMOTE CONTEXT: " + url + "]\n" + strippedText);
            setUrl("");
            onClose();
        } catch (err: any) {
            setError(err.message || "Failed to fetch content.");
        } finally {
            setIsFetching(false);
        }
    };

    if (!isOpen) return null;
    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
            <div className="w-full max-w-2xl glass-panel rounded-2xl flex flex-col max-h-[85vh] animate-slide-up">
