const App = () => {
  const getSaved = (key: string, def: any) => {
    const saved = localStorage.getItem(key);
    if (saved === null) return def;
    try { return JSON.parse(saved); } catch { return saved; }
  };

  const [view, setView] = useState<ViewState>("home");
  const [mode, setMode] = useState<AppMode>(getSaved("mode", "assistant"));
  const [activeProfileId, setActiveProfileId] = useState<string>(getSaved("profileId", "general"));
  const [selectedModel, setSelectedModel] = useState<string>(getSaved("selectedModel", "gemini-3-pro-preview"));

  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [toast, setToast] = useState<{msg: string, type: 'error' | 'info'} | null>(null);
  const [stats, setStats] = useState<KPIStats>({ totalMessages: 0, avgLatency: 0, lastLatency: 0, sessionStart: Date.now() });

  const [customKnowledge, setCustomKnowledge] = useState<string>(getSaved("ragContext", INITIAL_KNOWLEDGE));
  const [isKnowledgeOpen, setIsKnowledgeOpen] = useState(false);
  const [isWebSearchEnabled, setIsWebSearchEnabled] = useState(getSaved("searchEnabled", false));
  const [isThinkingEnabled, setIsThinkingEnabled] = useState(getSaved("thinkingEnabled", false));
  const [isImageGenEnabled, setIsImageGenEnabled] = useState(getSaved("imageGenEnabled", false));

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const recognitionRef = useRef<any>(null);

  useEffect(() => localStorage.setItem("mode", JSON.stringify(mode)), [mode]);
  useEffect(() => localStorage.setItem("profileId", JSON.stringify(activeProfileId)), [activeProfileId]);
  useEffect(() => localStorage.setItem("ragContext", JSON.stringify(customKnowledge)), [customKnowledge]);
  useEffect(() => localStorage.setItem("searchEnabled", JSON.stringify(isWebSearchEnabled)), [isWebSearchEnabled]);
  useEffect(() => localStorage.setItem("thinkingEnabled", JSON.stringify(isThinkingEnabled)), [isThinkingEnabled]);
  useEffect(() => localStorage.setItem("imageGenEnabled", JSON.stringify(isImageGenEnabled)), [isImageGenEnabled]);
  useEffect(() => localStorage.setItem("selectedModel", JSON.stringify(selectedModel)), [selectedModel]);

  const activeProfile = mode === 'assistant' 
    ? ASSISTANTS.find(p => p.id === activeProfileId) || ASSISTANTS[0]
    : SIMULATIONS.find(p => p.id === activeProfileId) || SIMULATIONS[0];

  const scrollToBottom = () => messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  useEffect(() => scrollToBottom(), [messages]);

  useEffect(() => {
    if (typeof window !== "undefined") {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (SpeechRecognition) {
        const recognition = new SpeechRecognition();
        recognition.continuous = false;
        recognition.interimResults = true;
        recognition.lang = "en-US";
        recognition.onresult = (e: any) => {
           const t = Array.from(e.results).map((r: any) => r[0].transcript).join("");
           setInputValue(t);
        };
        recognition.onend = () => setIsListening(false);
        recognitionRef.current = recognition;
      }
    }
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) return setToast({ msg: "Voice input not supported", type: "error" });
    if (isListening) recognitionRef.current.stop();
    else {
        recognitionRef.current.start();
        setIsListening(true);
    }
  };

  const selectProfile = (profile: Profile, newMode: AppMode) => {
      setMode(newMode);
      setActiveProfileId(profile.id);
      setMessages([]);
      setView('chat');
      if (newMode === 'simulation' && profile.startPrompt) {
          startSimulation(profile);
      }
  };

  const startSimulation = async (profile: Profile) => {
      setIsLoading(true);
      const startTime = Date.now();
      setMessages([{ role: "model", text: "", timestamp: startTime }]);
      try {
         await new Promise(r => setTimeout(r, 800));
         setMessages([{ role: "model", text: profile.startPrompt || "", timestamp: Date.now(), latency: 45 }]);
      } finally {
         setIsLoading(false);
      }
  };

  const handleSend = async () => {
    if (!inputValue.trim() || isLoading) return;
    const userMsg = inputValue;
    setInputValue("");
    setMessages(prev => [...prev, { role: "user", text: userMsg, timestamp: Date.now() }]);
    setIsLoading(true);

    const startTime = Date.now();
    let firstTokenTime = 0;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

      if (isImageGenEnabled) {
          const response = await ai.models.generateImages({
            model: 'imagen-3.0-generate-001',
            prompt: userMsg,
            config: { numberOfImages: 1, aspectRatio: '16:9' },
          });
          const base64 = response.generatedImages?.[0]?.image?.imageBytes;
          if (base64) {
             const imageUrl = `data:image/jpeg;base64,${base64}`;
             setMessages(prev => [...prev, { role: "model", text: `Generated visual for: "${userMsg}"`, image: imageUrl, timestamp: Date.now(), latency: Date.now() - startTime }]);
          } else { throw new Error("No image generated"); }
      } else {
          const history = messages.map(m => ({ role: m.role, parts: [{ text: m.text }] }));
          let sysInstruction = activeProfile.instruction;
          if (customKnowledge.trim()) {
              sysInstruction += `\n\n[CORE KNOWLEDGE BASE]\n${customKnowledge}\n\n[END KNOWLEDGE BASE]`;
          }
          const tools: Tool[] = [];
          if (isWebSearchEnabled) tools.push({ googleSearch: {} });
          const config: any = { systemInstruction: sysInstruction, tools: tools };
          if (isThinkingEnabled) config.thinkingConfig = { thinkingBudget: 32768 };

          const chat = ai.chats.create({ model: selectedModel, config: config, history: history });
          setMessages(prev => [...prev, { role: "model", text: "", timestamp: Date.now() }]);
          const result = await chat.sendMessageStream({ message: userMsg });

          let fullResponse = "";
          let groundingMetadata: GroundingMetadata | null = null;
          for await (const chunk of result) {
            if (!firstTokenTime) firstTokenTime = Date.now();
            fullResponse += chunk.text;
            if (chunk.candidates?.[0]?.groundingMetadata) groundingMetadata = chunk.candidates[0].groundingMetadata;
            setMessages(prev => {
              const updated = [...prev];
              const last = updated[updated.length - 1];
              if (last.role === "model") {
                  last.text = fullResponse;
                  if (groundingMetadata) last.groundingMetadata = groundingMetadata;
              }
              return updated;
            });
          }
          const latency = firstTokenTime - startTime;
          setMessages(prev => {
              const updated = [...prev];
              updated[updated.length - 1].latency = latency;
              return updated;
          });
      }
      setStats(prev => ({ ...prev, totalMessages: prev.totalMessages + 1, lastLatency: Date.now() - startTime }));
    } catch (error: any) {
      console.error(error);
      setMessages(prev => [...prev, { role: "model", text: "Connection failure or generation error.", isError: true, timestamp: Date.now() }]);
      setToast({ msg: "Failed to generate response.", type: 'error' });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen w-full font-sans text-gray-100 overflow-hidden relative selection:bg-cyan-500/30 selection:text-cyan-100">
      {toast && <Toast message={toast.msg} type={toast.type} onClose={() => setToast(null)} />}
      <KPIBoard stats={stats} />
      <KnowledgeModal isOpen={isKnowledgeOpen} onClose={() => setIsKnowledgeOpen(false)} value={customKnowledge} onChange={setCustomKnowledge} />

      <aside className="hidden md:flex flex-col w-72 glass-panel border-r border-white/5 z-20 shrink-0 h-full overflow-y-auto">
        <div className="p-6 pb-4">
            <div className="flex items-center gap-3 mb-6 cursor-pointer hover:opacity-80 transition-opacity" onClick={() => setView('home')}>
                <div className={`w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center shadow-lg shadow-indigo-500/20`}>
                    <span className="text-white font-bold text-xl">G3</span>
                </div>
                <div>
                    <h1 className="font-bold text-lg tracking-tight text-white leading-none">Gemini 3.0</h1>
                    <p className="text-[10px] text-gray-400 font-mono tracking-widest uppercase mt-1">Enterprise Edition</p>
                </div>
            </div>

            <button onClick={() => setView('home')} className={`w-full flex items-center gap-3 px-3 py-3 mb-6 rounded-xl transition-all ${view === 'home' ? 'bg-white/10 text-white font-medium' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}>
                <Icons.Home />
                <span>Dashboard</span>
            </button>

            {view === 'chat' && (
                <>
                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3 px-1 flex items-center gap-2">
                        {mode === 'assistant' ? <><Icons.Plugin /> Active Protocol</> : <><Icons.Sim /> Client Persona</>}
                    </h3>
                    <div className="space-y-1 mb-6">
                        {(mode === 'assistant' ? ASSISTANTS : SIMULATIONS).map(p => (
                            <button key={p.id} onClick={() => selectProfile(p, mode)} className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl text-left transition-all duration-200 border group ${activeProfileId === p.id ? "bg-white/10 border-white/10 text-white shadow-lg" : "border-transparent text-gray-400 hover:text-gray-200 hover:bg-white/5"}`}>
                                <div className={`w-8 h-8 rounded-lg flex items-center justify-center transition-colors ${activeProfileId === p.id ? 'bg-white/10 text-white' : 'bg-black/20 text-gray-500 group-hover:text-gray-300'}`}>{p.icon}</div>
                                <div className="flex-1 min-w-0"><div className="font-medium text-sm truncate">{p.name}</div></div>
                                {activeProfileId === p.id && <div className={`w-1.5 h-1.5 rounded-full shadow-[0_0_8px_currentColor] ${mode === 'simulation' ? 'bg-amber-400' : 'bg-cyan-400'}`}></div>}
                            </button>
                        ))}
                    </div>
                </>
            )}

            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3 px-1 flex items-center gap-2"><Icons.Cpu /> System Config</h3>
            <div className="space-y-4 mb-6">
                <div className="px-1">
                    <label className="text-[10px] font-bold text-gray-600 uppercase tracking-widest block mb-2">Neural Model</label>
                    <select 
                        value={selectedModel}
                        onChange={(e) => setSelectedModel(e.target.value)}
                        className="w-full bg-black/40 border border-white/10 rounded-xl px-3 py-2 text-xs text-gray-300 focus:outline-none focus:border-indigo-500/50 appearance-none cursor-pointer hover:bg-white/5 transition-colors"
                    >
                        {MODEL_OPTIONS.map(opt => (
                            <option key={opt.id} value={opt.id} className="bg-gray-900">{opt.name}</option>
                        ))}
                    </select>
                </div>
            </div>

            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3 px-1 flex items-center gap-2"><Icons.Database /> Knowledge Core</h3>
            <div className="space-y-2">
                <button onClick={() => setIsKnowledgeOpen(true)} className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl border transition-all ${customKnowledge ? 'bg-indigo-500/20 border-indigo-500/40 text-indigo-100' : 'bg-black/20 border-white/5 text-gray-400 hover:bg-white/5 hover:text-white'}`}>
                    <div className="w-8 h-8 rounded-lg bg-black/30 flex items-center justify-center"><Icons.Database /></div>
                    <div className="flex-1 text-left"><div className="text-xs font-medium">Neural Link</div><div className="text-[10px] opacity-60">{customKnowledge ? 'Context Active' : 'Configure R.A.G.'}</div></div>
