const KPIBoard = memo(({ stats }: { stats: KPIStats }) => {
    const elapsed = Math.floor((Date.now() - stats.sessionStart) / 1000);
    const mins = Math.floor(elapsed / 60);
    const secs = elapsed % 60;

    return (
        <div className="hidden lg:flex fixed bottom-6 right-6 z-40 gap-3">
             <div className="glass-panel px-4 py-2 rounded-full flex items-center gap-3 text-xs font-mono text-gray-400">
                <div className="flex items-center gap-1.5">
                    <Icons.Time />
                    <span className="text-gray-300">{mins}:{secs.toString().padStart(2, '0')}</span>
                </div>
                <div className="w-px h-3 bg-white/10"></div>
                <div className="flex items-center gap-1.5">
                    <Icons.Chart />
                    <span className={stats.lastLatency > 2000 ? "text-amber-400" : "text-emerald-400"}>
                        {stats.lastLatency > 0 ? `${stats.lastLatency}ms` : '--'}
                    </span>
                </div>
                <div className="w-px h-3 bg-white/10"></div>
                <div>
                    <span className="text-gray-300">{stats.totalMessages}</span> MSGS
                </div>
             </div>
        </div>
    );
});

