// --- TCM Organ Clock Visualizer ---
const TCMOrganClock = memo(() => {
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const currentHour = currentTime.getHours();

  const getActiveOrganIndex = () => {
    const index = ORGAN_CLOCK_DATA.findIndex(o => {
      if (o.startHour > o.endHour) { // Midnight crossing case (Gallbladder 23-1)
        return currentHour >= o.startHour || currentHour < o.endHour;
      }
      return currentHour >= o.startHour && currentHour < o.endHour;
    });
    return index === -1 ? 0 : index;
  };

  const activeIdx = getActiveOrganIndex();
  const activeOrgan = ORGAN_CLOCK_DATA[activeIdx];
  const rotation = -(activeIdx * 30);

  return (
    <div className="flex flex-col items-center justify-center p-4">
      <div className="relative w-56 h-56 rounded-full border border-white/10 flex items-center justify-center bg-black/20 shadow-inner">
        <div 
          className="absolute inset-0 transition-transform duration-1000 ease-in-out" 
          style={{ transform: `rotate(${rotation}deg)` }}
        >
          {ORGAN_CLOCK_DATA.map((o, i) => {
            const angle = i * 30;
            return (
              <div 
                key={o.name}
                className="absolute inset-0 flex flex-col items-center pt-2 origin-center"
                style={{ transform: `rotate(${angle}deg)` }}
              >
                <span 
                    className={`text-[9px] font-bold tracking-tighter uppercase transition-colors duration-500 ${i === activeIdx ? 'text-cyan-400 drop-shadow-[0_0_5px_rgba(34,211,238,0.5)]' : 'text-gray-600'}`}
                    style={{ transform: `rotate(${-angle - rotation}deg)` }}
                >
                  {o.name.split(' ')[0]}
                </span>
              </div>
            );
          })}
        </div>
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-0.5 h-1/2 bg-gradient-to-b from-cyan-400 to-transparent shadow-[0_0_15px_rgba(34,211,238,0.8)] z-10"></div>
        <div className="relative z-20 w-32 h-32 rounded-full glass-panel border border-white/10 flex flex-col items-center justify-center text-center p-2">
            <div className="text-[10px] text-gray-500 font-mono mb-1">{currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div>
            <div className="text-sm font-bold text-cyan-50 leading-tight mb-1">{activeOrgan.name}</div>
            <div className="text-[9px] text-gray-400 leading-tight italic line-clamp-2 px-2">"{activeOrgan.action}"</div>
        </div>
      </div>
      <div className="mt-6 w-full glass-panel-light p-4 rounded-xl border border-white/5">
        <div className="flex items-center gap-2 mb-2"><Icons.Time /><span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Biological Guidance</span></div>
        <p className="text-xs text-gray-300 leading-relaxed">Current Qi Focus: <span className="text-cyan-400 font-bold">{activeOrgan.name}</span>. TCM wisdom suggests focusing on <span className="text-white underline decoration-cyan-500/30">{activeOrgan.action.toLowerCase()}</span> during this cycle.</p>
      </div>
    </div>
  );
});

const KnowledgeModal = ({ isOpen, onClose, value, onChange }: { isOpen: boolean, onClose: () => void, value: string, onChange: (v: string) => void }) => {
    const [url, setUrl] = useState("");
    const [isFetching, setIsFetching] = useState(false);
    const [status, setStatus] = useState("");
    const [error, setError] = useState("");

    const handleFetchUrl = async () => {
        if (!url.trim()) return;
        setIsFetching(true);
        setStatus("Fetching raw content...");
        setError("");

        try {
            const response = await fetch(url);
            if (!response.ok) throw new Error("Fetch blocked. External websites often block browser-direct access (CORS).");

            const rawHtml = await response.text();
            setStatus("AI Processing & Summarizing...");

            // Clean HTML
            const cleanedText = rawHtml
                .replace(/<script\b[^>]*>([\s\S]*?)<\/script>/gmb, "")
                .replace(/<style\b[^>]*>([\s\S]*?)<\/style>/gmb, "")
                .replace(/<[^>]*>?/gm, ' ')
                .replace(/\s+/g, ' ')
                .trim()
                .substring(0, 15000); // Truncate to avoid context window issues

            // Use AI to process the fetched text into structured knowledge
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
            const summaryResult = await ai.models.generateContent({
                model: "gemini-3-flash-preview",
                contents: `Process this raw content into a structured set of facts for a RAG knowledge base. Extract only the most relevant technical details, definitions, and concepts. \n\nSOURCE URL: ${url}\n\nCONTENT:\n${cleanedText}`,
            });

            const processedText = summaryResult.text || "No insights extracted.";
            onChange(value + "\n\n[PROCESSED SOURCE: " + url + "]\n" + processedText);
            setUrl("");
            onClose();
        } catch (err: any) {
            setError(err.message || "Failed to process content.");
        } finally {
            setIsFetching(false);
            setStatus("");
        }
    };

    if (!isOpen) return null;
    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
            <div className="w-full max-w-2xl glass-panel rounded-2xl flex flex-col max-h-[85vh] animate-slide-up">
                <div className="p-6 border-b border-white/5 flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-indigo-500/20 text-indigo-300 rounded-lg"><Icons.Database /></div>
                        <div>
                            <h3 className="text-lg font-bold text-white">Neural Knowledge Base</h3>
                            <p className="text-xs text-gray-400">AI-powered content fetching & RAG processing</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="text-gray-400 hover:text-white">✕</button>
                </div>

                <div className="p-6 flex-1 flex flex-col min-h-0 space-y-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Target URL for AI Ingestion</label>
                        <div className="flex gap-2">
                            <input 
                                type="url"
                                placeholder="https://example.com/knowledge-doc"
                                className="flex-1 bg-black/30 border border-white/10 rounded-xl px-4 py-2 text-sm text-gray-300 focus:outline-none focus:border-indigo-500/50"
                                value={url}
                                onChange={(e) => setUrl(e.target.value)}
                            />
                            <button 
                                onClick={handleFetchUrl}
                                disabled={isFetching || !url}
                                className="px-5 py-2 bg-indigo-600 hover:bg-indigo-500 disabled:bg-gray-700 text-white rounded-xl text-xs font-bold transition-all flex items-center gap-2"
                            >
                                {isFetching ? <Icons.Loader /> : "Process with AI"}
                            </button>
                        </div>
                        {status && <p className="text-[10px] text-cyan-400 animate-pulse font-mono tracking-wide">{status}</p>}
                        {error && <p className="text-[10px] text-red-400 bg-red-500/10 p-2 rounded-lg border border-red-500/20">{error}</p>}
                    </div>

                    <div className="flex-1 flex flex-col min-h-0">
                        <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-2">Workspace (Current Context)</label>
                        <textarea 
                            className="flex-1 w-full bg-black/30 border border-white/10 rounded-xl p-4 text-sm font-mono text-gray-300 focus:outline-none focus:border-indigo-500/50 resize-none"
                            placeholder="Current knowledge context..."
                            value={value}
                            onChange={(e) => onChange(e.target.value)}
                        />
                    </div>

                    <div className="flex justify-between items-center mt-2">
                        <span className="text-xs text-gray-500 italic">Context size: {value.length} tokens</span>
                        <div className="flex gap-2">
                            <button onClick={() => onChange("")} className="px-4 py-2 text-gray-400 hover:text-white text-xs font-medium">Reset</button>
                            <button onClick={onClose} className="px-8 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg text-sm font-bold transition-colors shadow-lg">
                                Sync Knowledge
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

const MarkdownContent = memo(({ content }: { content: string }) => {
  const parts = content.split(/(```[\s\S]*?```)/g);
  return (
    <div className="prose prose-invert prose-sm max-w-none leading-relaxed">
      {parts.map((part, index) => {
        if (part.startsWith("```")) {
          const match = part.match(/```(\w*)\n([\s\S]*?)```/);
          const lang = match ? match[1] : "";
          const code = match ? match[2] : part.slice(3, -3);
          return (
            <div key={index} className="my-3 overflow-hidden rounded-lg border border-white/10 bg-black/40 backdrop-blur-sm group">
                <div className="flex justify-between items-center bg-white/5 px-3 py-1.5 border-b border-white/5">
                    <span className="text-[10px] text-gray-500 font-mono uppercase tracking-wider">{lang || 'TEXT'}</span>
                    <button onClick={() => copyToClipboard(code)} className="text-gray-500 hover:text-white transition-colors"><Icons.Copy /></button>
                </div>
                <pre className="!bg-transparent !p-4 !m-0 overflow-x-auto text-xs md:text-sm"><code>{code}</code></pre>
            </div>
          );
        }
        return <span key={index} dangerouslySetInnerHTML={{ __html: part.replace(/\*\*(.*?)\*\*/g, '<strong class="text-white font-bold">$1</strong>').replace(/\n/g, '<br/>') }} />;
      })}
    </div>
  );
});

