                onChange={e => setUrl(e.target.value)}
              />
              <button 
                onClick={handleFetchAndInject}
                disabled={isFetching || !url}
                className="px-6 py-2 bg-indigo-600 hover:bg-indigo-500 disabled:bg-gray-800 text-white rounded-xl text-xs font-bold transition-all flex items-center gap-2"
              >
                {isFetching ? <Icons.Loader /> : "AI Fetch"}
              </button>
            </div>
            {status && <p className="text-[10px] text-cyan-400 font-mono animate-pulse">{status}</p>}
          </div>
          <div className="flex-1 flex flex-col space-y-2 h-64">
            <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Active Neural Store</label>
            <textarea 
              className="flex-1 w-full bg-black border border-white/10 rounded-xl p-4 text-xs font-mono text-gray-400 resize-none focus:outline-none focus:border-indigo-500/50"
              value={value}
              onChange={e => onChange(e.target.value)}
            />
          </div>
        </div>
        <div className="p-6 border-t border-white/5 flex justify-end gap-3">
           <button onClick={onClose} className="px-6 py-2 bg-white text-black rounded-xl text-sm font-bold">Synchronize</button>
        </div>
      </div>
    </div>
  );
};

// --- App Component ---

const App = () => {
  const getSaved = (key: string, def: any) => {
    const s = localStorage.getItem(key);
    if (s === null) return def;
    try { return JSON.parse(s); } catch { return s; }
  };

  // UI State
  const [view, setView] = useState<ViewState>("home");
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isKnowledgeOpen, setIsKnowledgeOpen] = useState(false);

  // Persistence State
  const [selectedModel, setSelectedModel] = useState(getSaved("model", "gemini-3-pro-preview"));
  const [customKnowledge, setCustomKnowledge] = useState(getSaved("knowledge", INITIAL_KNOWLEDGE));
  const [activeProfileId, setActiveProfileId] = useState(getSaved("profile", "general"));
  const [isSearchOn, setIsSearchOn] = useState(getSaved("search", false));
  const [isMapsOn, setIsMapsOn] = useState(getSaved("maps", false));
  const [imgSize, setImgSize] = useState<"1K" | "2K" | "4K">(getSaved("imgSize", "1K"));

  // Refs for Live API & Voice
  const [isLiveActive, setIsLiveActive] = useState(false);
  const liveSessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);

  // Effects for Persistence
  useEffect(() => localStorage.setItem("model", JSON.stringify(selectedModel)), [selectedModel]);
  useEffect(() => localStorage.setItem("knowledge", JSON.stringify(customKnowledge)), [customKnowledge]);
  useEffect(() => localStorage.setItem("profile", JSON.stringify(activeProfileId)), [activeProfileId]);
  useEffect(() => localStorage.setItem("search", JSON.stringify(isSearchOn)), [isSearchOn]);
  useEffect(() => localStorage.setItem("maps", JSON.stringify(isMapsOn)), [isMapsOn]);
  useEffect(() => localStorage.setItem("imgSize", JSON.stringify(imgSize)), [imgSize]);

  const activeProfile = ASSISTANTS.find(p => p.id === activeProfileId) || ASSISTANTS[0];

  // --- Handlers ---

  const handleLiveToggle = async () => {
    if (isLiveActive) {
      if (liveSessionRef.current) liveSessionRef.current.close?.();
      setIsLiveActive(false);
      return;
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
    audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const outputNode = audioContextRef.current.createGain();
    outputNode.connect(audioContextRef.current.destination);

    const session = await ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-09-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
        systemInstruction: activeProfile.instruction
      },
      callbacks: {
        onmessage: async (msg: LiveServerMessage) => {
          const base64 = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64 && audioContextRef.current) {
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, audioContextRef.current.currentTime);
            const buffer = await decodeAudioData(decode(base64), audioContextRef.current, 24000, 1);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(outputNode);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += buffer.duration;
          }
        },
        onclose: () => setIsLiveActive(false),
        onerror: () => setIsLiveActive(false),
      }
    });

    liveSessionRef.current = session;
    setIsLiveActive(true);

    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    const inputContext = new AudioContext({ sampleRate: 16000 });
    const source = inputContext.createMediaStreamSource(stream);
    const processor = inputContext.createScriptProcessor(4096, 1, 1);
    processor.onaudioprocess = (ev) => {
      const data = ev.inputBuffer.getChannelData(0);
      const int16 = new Int16Array(data.length);
      for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
      session.sendRealtimeInput({ media: { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } });
    };
    source.connect(processor);
    processor.connect(inputContext.destination);
  };

  const handleSend = async () => {
    if (!inputValue.trim() || isLoading) return;
    const prompt = inputValue;
    setInputValue("");
    setMessages(prev => [...prev, { role: "user", text: prompt, timestamp: Date.now() }]);
    setIsLoading(true);
    const startTime = Date.now();

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

      // Image Gen Feature
      if (prompt.toLowerCase().includes("generate image") || prompt.toLowerCase().includes("create image")) {
        const response = await ai.models.generateContent({
          model: 'gemini-3-pro-image-preview',
          contents: { parts: [{ text: prompt }] },
          config: { imageConfig: { aspectRatio: "16:9", imageSize: imgSize } }
        });
        const imagePart = response.candidates[0].content.parts.find(p => p.inlineData);
        if (imagePart) {
           setMessages(prev => [...prev, { role: "model", text: "Image generated successfully.", image: `data:image/png;base64,${imagePart.inlineData.data}`, timestamp: Date.now(), latency: Date.now() - startTime }]);
           setIsLoading(false);
           return;
        }
      }

      // Video Gen Feature (Veo)
      if (prompt.toLowerCase().includes("generate video")) {
        const op = await ai.models.generateVideos({
          model: 'veo-3.1-fast-generate-preview',
          prompt: prompt,
          config: { resolution: '720p', aspectRatio: '16:9' }
        });
        let res = op;
        while (!res.done) {
          await new Promise(r => setTimeout(r, 10000));
          res = await ai.operations.getVideosOperation({ operation: res });
        }
        const uri = res.response?.generatedVideos?.[0]?.video?.uri;
        if (uri) {
           const vidResp = await fetch(`${uri}&key=${process.env.API_KEY}`);
           const blob = await vidResp.blob();
           setMessages(prev => [...prev, { role: "model", text: "Video synthesis complete.", video: URL.createObjectURL(blob), timestamp: Date.now(), latency: Date.now() - startTime }]);
           setIsLoading(false);
           return;
        }
      }

      // Standard Chat / Grounding
      const tools: Tool[] = [];
      if (isSearchOn) tools.push({ googleSearch: {} });
      if (isMapsOn) tools.push({ googleMaps: {} });

      const modelToUse = isMapsOn ? 'gemini-2.5-flash' : selectedModel;
      const sysInstruction = `${activeProfile.instruction}\n\n[KNOWLEDGE BASE]\n${customKnowledge}`;

      const chat = ai.chats.create({ 
        model: modelToUse, 
        config: { systemInstruction: sysInstruction, tools } 
      });

      setMessages(prev => [...prev, { role: "model", text: "", timestamp: Date.now() }]);
      const stream = await chat.sendMessageStream({ message: prompt });
      let fullText = "";
      let metadata: GroundingMetadata | null = null;

      for await (const chunk of stream) {
        fullText += chunk.text;
        if (chunk.candidates?.[0]?.groundingMetadata) metadata = chunk.candidates[0].groundingMetadata;
        setMessages(prev => {
          const copy = [...prev];
          const last = copy[copy.length - 1];
          last.text = fullText;
          last.groundingMetadata = metadata;
          return copy;
        });
      }
      setMessages(prev => {
        const copy = [...prev];
        copy[copy.length - 1].latency = Date.now() - startTime;
        return copy;
      });
    } catch (e: any) {
      setMessages(prev => [...prev, { role: "model", text: "Error: " + e.message, isError: true, timestamp: Date.now() }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen bg-black text-white font-sans overflow-hidden">
      <KnowledgeModal isOpen={isKnowledgeOpen} onClose={() => setIsKnowledgeOpen(false)} value={customKnowledge} onChange={setCustomKnowledge} />

      <aside className="w-72 bg-[#0a0a0c] border-r border-white/5 flex flex-col p-6 space-y-8 z-20">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center font-bold text-xl">S</div>
          <div><h1 className="font-bold">Shaman AI</h1><p className="text-[10px] text-gray-500 uppercase tracking-widest">v3.0 Hub</p></div>
        </div>

        <nav className="flex-1 space-y-2">
            <button onClick={() => setView('home')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${view==='home'?'bg-white/10 text-white':'text-gray-500 hover:bg-white/5'}`}>
                <Icons.Bot /> Dashboard
            </button>
            <button onClick={() => setView('chat')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${view==='chat'?'bg-white/10 text-white':'text-gray-500 hover:bg-white/5'}`}>
                <Icons.Copy /> Neural Chat
            </button>
        </nav>

        <div className="space-y-4 border-t border-white/5 pt-6">
            <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-600 uppercase">Model</label>
                <select value={selectedModel} onChange={e => setSelectedModel(e.target.value)} className="w-full bg-black border border-white/10 rounded-xl px-3 py-2 text-xs text-gray-300">
                    {MODEL_OPTIONS.map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                </select>
            </div>
            <div className="flex items-center justify-between">
                <span className="text-xs text-gray-400">Search Grounding</span>
                <input type="checkbox" checked={isSearchOn} onChange={e => setIsSearchOn(e.target.checked)} className="accent-indigo-500" />
            </div>
            <div className="flex items-center justify-between">
                <span className="text-xs text-gray-400">Maps Grounding</span>
                <input type="checkbox" checked={isMapsOn} onChange={e => setIsMapsOn(e.target.checked)} className="accent-green-500" />
            </div>
            <button onClick={() => setIsKnowledgeOpen(true)} className="w-full flex items-center gap-2 px-4 py-3 bg-indigo-900/30 text-indigo-300 rounded-xl text-xs font-bold hover:bg-indigo-900/50 transition-all">
                <Icons.Database /> Sync Knowledge
            </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative h-full">
        {view === 'home' ? (
          <div className="flex-1 overflow-y-auto p-12 space-y-12">
            <div className="max-w-4xl mx-auto space-y-4 text-center">
              <h1 className="text-5xl font-black tracking-tight bg-gradient-to-br from-white to-gray-600 bg-clip-text text-transparent">Cognitive Health Nexus</h1>
              <p className="text-gray-400 max-w-2xl mx-auto">Explore Traditional Wisdom through Neural Architectures. Persistent, Grounded, and Real-time.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-5xl mx-auto">
               <div className="bg-[#0f0f12] border border-white/5 rounded-3xl p-8 hover:border-indigo-500/20 transition-all group">
                  <div className="w-12 h-12 rounded-2xl bg-indigo-500/10 text-indigo-400 flex items-center justify-center mb-6 group-hover:scale-110 transition-transform"><Icons.Audio /></div>
                  <h3 className="text-xl font-bold mb-2">Live Conversational AI</h3>
                  <p className="text-sm text-gray-500 mb-6">Real-time voice interaction powered by Native Audio.</p>
                  <button onClick={handleLiveToggle} className={`w-full py-3 rounded-2xl font-bold transition-all ${isLiveActive?'bg-red-600 shadow-[0_0_20px_rgba(220,38,38,0.4)]':'bg-indigo-600 shadow-[0_0_20px_rgba(79,70,229,0.3)] hover:bg-indigo-500'}`}>
                    {isLiveActive ? "Stop Session" : "Start Live Session"}
                  </button>
               </div>
               <div className="bg-[#0f0f12] border border-white/5 rounded-3xl p-8 hover:border-pink-500/20 transition-all group">
                  <div className="w-12 h-12 rounded-2xl bg-pink-500/10 text-pink-400 flex items-center justify-center mb-6 group-hover:scale-110 transition-transform"><Icons.Movie /></div>
                  <h3 className="text-xl font-bold mb-2">Veo Video Generation</h3>
                  <p className="text-sm text-gray-500 mb-6">Cinematic 720p synthesis from prompts.</p>
                  <button onClick={() => setView('chat')} className="w-full py-3 bg-pink-600 rounded-2xl font-bold hover:bg-pink-500 transition-all">Go to Studio</button>
               </div>
            </div>
          </div>
        ) : (
          <>
            <div className="flex-1 overflow-y-auto p-6 space-y-6 w-full max-w-4xl mx-auto">
                {messages.length === 0 && (
                    <div className="h-full flex flex-col items-center justify-center opacity-30 text-center space-y-4">
                        <Icons.Bot />
                        <p className="text-sm italic">Neural Link established. Awaiting input...</p>
                    </div>
                )}
                {messages.map((m, i) => (
                    <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-[85%] p-5 rounded-3xl border ${m.role === 'user' ? 'bg-indigo-600/10 border-indigo-500/20 text-white' : 'bg-[#0f0f12] border-white/5 text-gray-300'}`}>
                            {m.image && <img src={m.image} className="rounded-xl mb-3 w-full" />}
                            {m.video && <video src={m.video} controls className="rounded-xl mb-3 w-full" />}
                            <p className="text-sm leading-relaxed whitespace-pre-wrap">{m.text}</p>
                            {m.groundingMetadata?.groundingChunks?.map((c, idx) => (
                                <a key={idx} href={c.web?.uri || c.maps?.uri} target="_blank" className="inline-flex items-center gap-1 mt-3 px-2 py-1 bg-white/5 rounded text-[10px] text-indigo-400 hover:text-white transition-colors mr-2">
                                    <Icons.Link /> {c.web?.title || c.maps?.title || "Source"}
                                </a>
                            ))}
                        </div>
                    </div>
                ))}
                {isLoading && <div className="flex justify-start"><div className="p-4 bg-white/5 rounded-2xl animate-pulse"><Icons.Loader /></div></div>}
            </div>

            <footer className="p-6 bg-gradient-to-t from-black to-transparent">
              <div className="max-w-4xl mx-auto flex items-end gap-3 bg-[#0f0f12] p-2 rounded-2xl border border-white/10 shadow-2xl focus-within:border-indigo-500/50 transition-all">
                <div className="flex gap-1 p-2">
                   <select value={imgSize} onChange={e => setImgSize(e.target.value as any)} className="bg-transparent text-[10px] font-bold text-gray-500 hover:text-white cursor-pointer transition-colors">
                      <option value="1K">1K</option>
                      <option value="2K">2K</option>
                      <option value="4K">4K</option>
                   </select>
                </div>
                <textarea 
                  className="flex-1 bg-transparent p-3 text-sm outline-none resize-none max-h-40 min-h-[48px]"
                  placeholder="Ask Shaman AI, generate image, or synth video..."
                  rows={1}
                  value={inputValue}
                  onChange={e => setInputValue(e.target.value)}
                  onKeyDown={e => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
                />
                <button onClick={handleSend} disabled={isLoading} className="p-3 bg-white text-black rounded-xl hover:bg-indigo-500 hover:text-white transition-all">
                  {isLoading ? <Icons.Stop /> : <Icons.Send />}
                </button>
              </div>
            </footer>
          </>
        )}
      </main>
    </div>
  );
};

