  groundingChunks?: GroundingChunk[];
}

interface Message {
  role: Role;
  text: string;
  image?: string; // Base64 Data URI
  video?: string; // Blob URL
  isError?: boolean;
  timestamp: number;
  latency?: number; // ms
  groundingMetadata?: GroundingMetadata | null;
}

interface Profile {
  id: string;
  name: string;
  description: string;
  instruction: string;
  icon: React.ReactNode;
  color: string;
  startPrompt?: string;
}

