};

// --- Configs & Consts ---

const MODEL_OPTIONS = [
  { id: 'gemini-3-pro-preview', name: 'Gemini 3 Pro', desc: 'Reasoning & Coding' },
  { id: 'gemini-3-flash-preview', name: 'Gemini 3 Flash', desc: 'Fast & Grounded' },
