// --- Utils ---
function decode(base64: string): Uint8Array {
  const bin = atob(base64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

function encode(bytes: Uint8Array): string {
  let bin = '';
  for (let i = 0; i < bytes.byteLength; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}

async function decodeAudio(data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  return buffer;
}

// --- TCM Organ Clock Visualizer Component ---
const TCMOrganClock = () => {
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const hour = time.getHours();

  const activeOrganIndex = ORGAN_CLOCK_DATA.findIndex(o => {
    if (o.startHour > o.endHour) return hour >= o.startHour || hour < o.endHour;
    return hour >= o.startHour && hour < o.endHour;
  });

  const activeOrgan = ORGAN_CLOCK_DATA[activeOrganIndex];
  // Calculate rotation: each organ is 30 degrees (360/12). 
  // We want the active organ at the top (0 degrees).
  const rotation = -(activeOrganIndex * 30);

  return (
    <div className="flex flex-col items-center bg-[#0f0f12] p-8 rounded-3xl border border-white/5 w-full max-w-sm mx-auto shadow-2xl">
      <div className="flex items-center gap-2 mb-6 text-indigo-400">
        <Icons.Clock />
        <span className="text-[10px] font-bold uppercase tracking-widest">Organ Qi Cycle</span>
      </div>

      <div className="relative w-64 h-64 flex items-center justify-center">
        {/* The Outer Rotating Dial */}
        <div 
          className="absolute inset-0 rounded-full border border-white/10 transition-transform duration-1000 ease-in-out"
          style={{ transform: `rotate(${rotation}deg)` }}
        >
          {ORGAN_CLOCK_DATA.map((organ, i) => {
            const angle = i * 30;
            const isHighlight = i === activeOrganIndex;
            return (
              <div 
                key={organ.name}
                className="absolute inset-0 flex flex-col items-center pt-2 origin-center"
                style={{ transform: `rotate(${angle}deg)` }}
              >
                <div 
                  className={`text-[8px] font-bold uppercase transition-colors duration-500 ${isHighlight ? 'text-indigo-400' : 'text-gray-600'}`}
                  style={{ transform: `rotate(${-angle - rotation}deg)` }}
                >
                  {organ.name}
                </div>
              </div>
            );
          })}
        </div>

        {/* Central Indicator / Digital Time */}
        <div className="z-10 bg-black/40 backdrop-blur-md w-24 h-24 rounded-full border border-indigo-500/20 flex flex-col items-center justify-center shadow-inner">
          <div className="text-xl font-bold text-white leading-none">
            {time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false })}
          </div>
          <div className="text-[8px] text-indigo-400 mt-1 uppercase font-mono tracking-tighter">Current Qi</div>
        </div>

        {/* The Fixed Indicator Hand (Top) */}
        <div className="absolute top-0 left-1/2 -translate-x-1/2 -translate-y-1 w-0.5 h-8 bg-gradient-to-b from-indigo-500 to-transparent z-20 shadow-[0_0_10px_rgba(99,102,241,0.5)]"></div>
      </div>

      <div className="mt-8 text-center space-y-2">
        <h3 className="text-lg font-bold text-white">{activeOrgan.name} Phase</h3>
        <p className="text-xs text-gray-500 italic px-4 leading-relaxed">
          "{activeOrgan.action}"
        </p>
        <div className="pt-4 border-t border-white/5 mt-4">
          <p className="text-[10px] text-gray-400 uppercase tracking-widest font-bold mb-1">Biological Guidance</p>
          <p className="text-xs text-indigo-300 font-medium leading-relaxed">
            The body is currently focused on {activeOrgan.name.toLowerCase()} activities: {activeOrgan.action.toLowerCase()}.
          </p>
        </div>
      </div>
    </div>
  );
};

// --- Main App ---
const App = () => {
  const [view, setView] = useState<ViewState>("home");
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [isLive, setIsLive] = useState(false);
  const [imgSize, setImgSize] = useState<"1K" | "2K" | "4K">("1K");
  const [isSearch, setIsSearch] = useState(true);
  const [isMaps, setIsMaps] = useState(false);

  const liveSessionRef = useRef<any>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);

  const checkKey = async () => {
    if (!(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }
  };

  const handleLiveToggle = async () => {
    if (isLive) {
      liveSessionRef.current?.close();
      setIsLive(false);
      return;
    }

    await checkKey();
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const outputNode = audioCtxRef.current.createGain();
    outputNode.connect(audioCtxRef.current.destination);

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } }
      },
      callbacks: {
        onmessage: async (msg: LiveServerMessage) => {
          const base64 = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64 && audioCtxRef.current) {
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, audioCtxRef.current.currentTime);
            const buffer = await decodeAudio(decode(base64), audioCtxRef.current);
            const source = audioCtxRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(outputNode);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += buffer.duration;
          }
        },
        onclose: () => setIsLive(false),
        onerror: () => setIsLive(false)
      }
    });

    const session = await sessionPromise;
    liveSessionRef.current = session;
    setIsLive(true);

    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    const inputCtx = new AudioContext({ sampleRate: 16000 });
    const source = inputCtx.createMediaStreamSource(stream);
    const processor = inputCtx.createScriptProcessor(4096, 1, 1);
    processor.onaudioprocess = (e) => {
      const data = e.inputBuffer.getChannelData(0);
      const int16 = new Int16Array(data.length);
      for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
      sessionPromise.then(s => s.sendRealtimeInput({ media: { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } }));
    };
    source.connect(processor);
    processor.connect(inputCtx.destination);
  };

  const handleSend = async () => {
    if (!input.trim() || loading) return;
    const prompt = input;
    setInput("");
    setMessages(prev => [...prev, { role: "user", text: prompt, timestamp: Date.now() }]);
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Feature: Veo Video
      if (prompt.toLowerCase().includes("video")) {
        await checkKey();
        let op = await ai.models.generateVideos({
          model: 'veo-3.1-fast-generate-preview',
          prompt,
          config: { resolution: '720p', aspectRatio: '16:9' }
        });
        while (!op.done) {
          await new Promise(r => setTimeout(r, 10000));
          op = await ai.operations.getVideosOperation({ operation: op });
        }
        const videoUrl = `${op.response?.generatedVideos?.[0]?.video?.uri}&key=${process.env.API_KEY}`;
        const blob = await (await fetch(videoUrl)).blob();
        setMessages(prev => [...prev, { role: "model", text: "Video complete.", video: URL.createObjectURL(blob), timestamp: Date.now() }]);
        setLoading(false);
        return;
      }

      // Feature: High Quality Image Gen
      if (prompt.toLowerCase().includes("generate image")) {
        await checkKey();
        const resp = await ai.models.generateContent({
          model: 'gemini-3-pro-image-preview',
          contents: { parts: [{ text: prompt }] },
          config: { imageConfig: { aspectRatio: "1:1", imageSize: imgSize } }
        });
        const imgPart = resp.candidates[0].content.parts.find(p => p.inlineData);
        if (imgPart) {
          setMessages(prev => [...prev, { role: "model", text: "Generated.", image: `data:image/png;base64,${imgPart.inlineData.data}`, timestamp: Date.now() }]);
          setLoading(false);
          return;
        }
      }

      // Feature: Chat with Grounding
      const tools: Tool[] = [];
      if (isSearch) tools.push({ googleSearch: {} });
      if (isMaps) tools.push({ googleMaps: {} });

      const model = isMaps ? 'gemini-2.5-flash' : 'gemini-3-pro-preview';
      const chat = ai.chats.create({ model, config: { tools } });
      const stream = await chat.sendMessageStream({ message: prompt });

      setMessages(prev => [...prev, { role: "model", text: "", timestamp: Date.now() }]);
      let fullText = "";
      let metadata: GroundingMetadata | null = null;

      for await (const chunk of stream) {
        fullText += chunk.text;
        if (chunk.candidates?.[0]?.groundingMetadata) metadata = chunk.candidates[0].groundingMetadata;
        setMessages(prev => {
          const last = [...prev];
          last[last.length - 1] = { ...last[last.length - 1], text: fullText, groundingMetadata: metadata };
          return last;
        });
      }
    } catch (e: any) {
      setMessages(prev => [...prev, { role: "model", text: `Error: ${e.message}`, isError: true, timestamp: Date.now() }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex h-screen bg-black text-white font-sans overflow-hidden">
      <aside className="w-72 bg-[#0a0a0c] border-r border-white/5 flex flex-col p-6 space-y-8">
