        </nav>
        <div className="pt-6 border-t border-white/5 space-y-4">
          <div className="space-y-2">
            <label className="text-[10px] font-bold text-gray-600 uppercase">Image Quality</label>
            <select value={imgSize} onChange={e => setImgSize(e.target.value as any)} className="w-full bg-black border border-white/10 rounded-lg p-2 text-xs">
              <option value="1K">1K (Standard)</option>
              <option value="2K">2K (High)</option>
              <option value="4K">4K (Ultra)</option>
            </select>
          </div>
          <label className="flex items-center justify-between text-xs text-gray-400">
            Search Grounding <input type="checkbox" checked={isSearch} onChange={e=>setIsSearch(e.target.checked)}/>
          </label>
          <label className="flex items-center justify-between text-xs text-gray-400">
            Maps Grounding <input type="checkbox" checked={isMaps} onChange={e=>setIsMaps(e.target.checked)}/>
          </label>
          <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="text-[10px] text-gray-600 block text-center">Billing Info</a>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-full relative">
        {view === 'home' ? (
          <div className="flex-1 flex flex-col items-center justify-start overflow-y-auto p-12 space-y-12">
            <h2 className="text-5xl font-black bg-gradient-to-br from-white to-gray-600 bg-clip-text text-transparent">Nexus Hub</h2>

            <div className="w-full flex flex-col items-center">
              <TCMOrganClock />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-3xl">
              <button onClick={handleLiveToggle} className={`p-8 rounded-3xl border border-white/5 transition-all ${isLive?'bg-red-600':'bg-[#0f0f12] hover:border-indigo-500/50'}`}>
                <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center mx-auto mb-4"><Icons.Mic active={isLive} /></div>
                <div className="font-bold">{isLive ? "End Live Session" : "Start Live Voice"}</div>
              </button>
              <button onClick={() => setView('studio')} className="p-8 rounded-3xl bg-[#0f0f12] border border-white/5 hover:border-pink-500/50 transition-all">
                <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center mx-auto mb-4"><Icons.Movie /></div>
                <div className="font-bold">Media Studio</div>
              </button>
            </div>
          </div>
        ) : (
          <>
            <div className="flex-1 overflow-y-auto p-6 space-y-6 max-w-4xl mx-auto w-full">
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-5 rounded-3xl border ${m.role === 'user' ? 'bg-indigo-600/10 border-indigo-500/20' : 'bg-[#0f0f12] border-white/5'}`}>
                    {m.image && <img src={m.image} className="rounded-xl mb-4 max-w-full" />}
                    {m.video && <video src={m.video} controls className="rounded-xl mb-4 max-w-full" />}
                    <p className="text-sm whitespace-pre-wrap leading-relaxed">{m.text}</p>
                    {m.groundingMetadata?.groundingChunks?.map((c, idx) => (
                      <a key={idx} href={c.web?.uri || c.maps?.uri} target="_blank" className="inline-flex items-center gap-1.5 mt-3 mr-3 px-3 py-1 bg-white/5 rounded-full text-[10px] text-indigo-400 hover:bg-white/10">
                        <Icons.Link /> {c.web?.title || c.maps?.title || "Source"}
                      </a>
                    ))}
                  </div>
                </div>
              ))}
              {loading && <div className="p-4 bg-white/5 w-12 h-12 rounded-2xl animate-pulse"><Icons.Loader /></div>}
            </div>
