  const rotation = -(activeOrganIndex * 30);

  return (
    <div className="flex flex-col items-center bg-zinc-900/50 backdrop-blur-xl p-8 rounded-[2rem] border border-white/10 w-full max-w-sm mx-auto shadow-2xl animate-slide-up">
