            const isHighlight = i === activeOrganIndex;
            return (
              <div key={organ.name} className="absolute inset-0 flex flex-col items-center pt-4 origin-center" style={{ transform: `rotate(${angle}deg)` }}>
                <div className={`text-[9px] font-semibold transition-all duration-700 ${isHighlight ? 'text-indigo-400 scale-125' : 'text-zinc-600'}`} style={{ transform: `rotate(${-angle - rotation}deg)` }}>
                  {organ.name}
                </div>
              </div>
            );
          })}
        </div>

        <div className="z-10 bg-black/60 backdrop-blur-lg w-28 h-28 rounded-full border border-indigo-500/30 flex flex-col items-center justify-center">
          <div className="text-2xl font-mono font-bold text-white tracking-tight">
            {time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false })}
          </div>
          <div className="text-[9px] text-indigo-400 mt-1 uppercase font-bold tracking-widest opacity-80">Phase Active</div>
        </div>

        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-1 h-10 bg-gradient-to-b from-indigo-500 to-transparent z-20 rounded-full"></div>
      </div>

      <div className="mt-10 text-center space-y-4">
        <div>
          <h3 className="text-xl font-bold text-white mb-1">{activeOrgan.name}</h3>
          <p className="text-sm text-indigo-300 font-medium">{activeOrgan.action}</p>
        </div>
        <div className="pt-4 border-t border-white/5">
          <p className="text-[10px] text-zinc-500 uppercase tracking-widest font-black">Lifestyle Advisory</p>
          <p className="text-xs text-zinc-400 leading-relaxed mt-2">Optimal window for metabolic {activeOrgan.name.toLowerCase()} support.</p>
        </div>
      </div>
    </div>
  );
};

// --- App ---
const App = () => {
  // Restore state from localStorage
  const savedState = JSON.parse(localStorage.getItem('shaman_ai_state') || '{}');

  const [view, setView] = useState<ViewState>(savedState.view || "home");
  const [messages, setMessages] = useState<Message[]>(savedState.messages || []);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [imgSize, setImgSize] = useState<"1K" | "2K" | "4K">(savedState.imgSize || "1K");
  const [aspectRatio, setAspectRatio] = useState<string>(savedState.aspectRatio || "16:9");
  const [useThinking, setUseThinking] = useState(savedState.useThinking || false);
  const [activeProfile, setActiveProfile] = useState<ProfileType>(savedState.activeProfile || "cos");
  const [isLive, setIsLive] = useState(false);
  const [mediaFile, setMediaFile] = useState<{data: string, type: string} | null>(null);

  const liveSessionRef = useRef<any>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const profile = PROFILES.find(p => p.id === activeProfile) || PROFILES[0];

  // Persistence side-effect
  useEffect(() => {
    localStorage.setItem('shaman_ai_state', JSON.stringify({
      view,
      messages,
      imgSize,
      aspectRatio,
      useThinking,
      activeProfile
    }));
  }, [view, messages, imgSize, aspectRatio, useThinking, activeProfile]);

  const clearHistory = () => {
    if (confirm("Clear session intelligence?")) {
      setMessages([]);
    }
  };

  const checkKey = async () => {
    if (!(await (window as any).aistudio.hasSelectedApiKey())) {
      await (window as any).aistudio.openSelectKey();
    }
  };

  const handleLiveVoice = async () => {
    if (isLive) {
      liveSessionRef.current?.close();
      setIsLive(false);
      return;
    }
    await checkKey();
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const outputNode = audioCtxRef.current.createGain();
    outputNode.connect(audioCtxRef.current.destination);

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
        systemInstruction: profile.instruction
      },
      callbacks: {
        onmessage: async (msg: LiveServerMessage) => {
          const base64 = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64 && audioCtxRef.current) {
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, audioCtxRef.current.currentTime);
            const buffer = await decodeAudioData(decodeBase64(base64), audioCtxRef.current);
            const source = audioCtxRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(outputNode);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += buffer.duration;
          }
        },
        onclose: () => setIsLive(false),
        onerror: () => setIsLive(false)
      }
    });

    const session = await sessionPromise;
    liveSessionRef.current = session;
    setIsLive(true);

    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    const inputCtx = new AudioContext({ sampleRate: 16000 });
    const source = inputCtx.createMediaStreamSource(stream);
    const processor = inputCtx.createScriptProcessor(4096, 1, 1);
    processor.onaudioprocess = (e) => {
      const data = e.inputBuffer.getChannelData(0);
      const int16 = new Int16Array(data.length);
      for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
      sessionPromise.then(s => s.sendRealtimeInput({ media: { data: encodeBase64(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } }));
    };
    source.connect(processor);
    processor.connect(inputCtx.destination);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      setMediaFile({
        data: ev.target?.result as string,
        type: file.type
      });
    };
    reader.readAsDataURL(file);
  };

  const handleSend = async () => {
    if (!input.trim() && !mediaFile) return;
    const userPrompt = input;
    const attachedMedia = mediaFile;
    setInput("");
    setMediaFile(null);
    setLoading(true);

    const userMsg: Message = { role: "user", text: userPrompt, timestamp: Date.now() };
    if (attachedMedia?.type.startsWith('image')) userMsg.image = attachedMedia.data;
    if (attachedMedia?.type.startsWith('video')) userMsg.video = attachedMedia.data;
    setMessages(prev => [...prev, userMsg]);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const lcPrompt = userPrompt.toLowerCase();

      if (lcPrompt.includes("generate video") || (lcPrompt.includes("animate") && attachedMedia)) {
        await checkKey();
        const freshAi = new GoogleGenAI({ apiKey: process.env.API_KEY });
        let config: any = { resolution: '720p', aspectRatio: aspectRatio as any };
        let payload: any = { model: 'veo-3.1-fast-generate-preview', prompt: userPrompt, config };

        if (attachedMedia?.type.startsWith('image')) {
          payload.image = { imageBytes: attachedMedia.data.split(',')[1], mimeType: attachedMedia.type };
        }

        let op = await freshAi.models.generateVideos(payload);
        while (!op.done) {
          await new Promise(r => setTimeout(r, 10000));
          op = await freshAi.operations.getVideosOperation({ operation: op });
        }
        const uri = op.response?.generatedVideos?.[0]?.video?.uri;
        const resp = await fetch(`${uri}&key=${process.env.API_KEY}`);
        const blob = await resp.blob();
        setMessages(prev => [...prev, { role: "model", text: "Synthesis complete.", video: URL.createObjectURL(blob), timestamp: Date.now() }]);
      }

      else if (lcPrompt.includes("generate image") || lcPrompt.includes("create image")) {
        await checkKey();
        const freshAi = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const resp = await freshAi.models.generateContent({
          model: 'gemini-3-pro-image-preview',
          contents: { parts: [{ text: userPrompt }] },
          config: { imageConfig: { aspectRatio: aspectRatio as any, imageSize: imgSize as any } }
        });
        const imgPart = resp.candidates[0].content.parts.find(p => p.inlineData);
        if (imgPart) {
          setMessages(prev => [...prev, { role: "model", text: "Generated artifact.", image: `data:image/png;base64,${imgPart.inlineData.data}`, timestamp: Date.now() }]);
        }
      }

      else if (attachedMedia?.type.startsWith('image') && (lcPrompt.includes("filter") || lcPrompt.includes("edit") || lcPrompt.includes("add") || lcPrompt.includes("remove"))) {
        const resp = await ai.models.generateContent({
          model: 'gemini-2.5-flash-image',
          contents: {
            parts: [
              { inlineData: { data: attachedMedia.data.split(',')[1], mimeType: attachedMedia.type } },
              { text: userPrompt }
            ]
          }
        });
        const editedPart = resp.candidates[0].content.parts.find(p => p.inlineData);
        if (editedPart) {
          setMessages(prev => [...prev, { role: "model", text: "Refined output.", image: `data:image/png;base64,${editedPart.inlineData.data}`, timestamp: Date.now() }]);
        }
      }

      else if (lcPrompt.startsWith("say ") || lcPrompt.startsWith("speak ")) {
        const resp = await ai.models.generateContent({
          model: "gemini-2.5-flash-preview-tts",
          contents: [{ parts: [{ text: userPrompt.replace(/^(say|speak)\s+/i, "") }] }],
          config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }
          }
        });
        const audioData = resp.candidates[0].content.parts[0].inlineData?.data;
        if (audioData) {
          setMessages(prev => [...prev, { role: "model", text: "Vocalized response.", audio: audioData, timestamp: Date.now() }]);
        }
      }

      else {
        const parts: any[] = [{ text: userPrompt }];
        if (attachedMedia) {
          parts.push({ inlineData: { data: attachedMedia.data.split(',')[1], mimeType: attachedMedia.type } });
        }

        const config: any = {
          tools: [{ googleSearch: {} }],
          systemInstruction: profile.instruction,
          thinkingConfig: useThinking ? { thinkingBudget: 32768 } : undefined
        };

        const model = useThinking ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
        const stream = await ai.models.generateContentStream({ model, contents: { parts }, config });

        let fullText = "";
        let meta: GroundingMetadata | null = null;
        setMessages(prev => [...prev, { role: "model", text: "", timestamp: Date.now() }]);

        for await (const chunk of stream) {
          const c = chunk as GenerateContentResponse;
          fullText += c.text || "";
          if (c.candidates?.[0]?.groundingMetadata) meta = c.candidates[0].groundingMetadata;
          setMessages(prev => {
            const copy = [...prev];
            copy[copy.length - 1] = { ...copy[copy.length - 1], text: fullText, groundingMetadata: meta };
            return copy;
          });
        }
      }
    } catch (e: any) {
      setMessages(prev => [...prev, { role: "model", text: `Protocol Error: ${e.message}`, isError: true, timestamp: Date.now() }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`flex h-screen bg-black text-zinc-100 font-sans overflow-hidden accent-${profile.color}-500`}>
      <aside className="w-80 bg-zinc-950 border-r border-white/5 flex flex-col p-6 space-y-8 z-30">
        <div className="flex items-center gap-3">
          <div className={`w-10 h-10 rounded-xl bg-${profile.color}-600 flex items-center justify-center font-bold text-xl shadow-lg shadow-${profile.color}-500/20 transition-colors duration-500`}>S</div>
          <div>
            <h1 className="font-bold text-lg tracking-tight">Shaman AI</h1>
            <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">Profile Persistence active</p>
          </div>
        </div>

        <nav className="flex-1 space-y-1.5 overflow-y-auto pr-2 scrollbar-none">
          <div className="pb-2 text-[10px] font-bold text-zinc-600 uppercase tracking-widest px-4">Navigation</div>
          <button onClick={() => setView('home')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${view==='home'?'bg-white/5 text-white border border-white/10':'text-zinc-500 hover:bg-white/5'}`}>Home</button>
          <button onClick={() => setView('studio')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${view==='studio'?'bg-white/5 text-white border border-white/10':'text-zinc-500 hover:bg-white/5'}`}>Studio</button>

          <div className="pt-4 pb-2 text-[10px] font-bold text-zinc-600 uppercase tracking-widest px-4">Active Profile</div>
          <div className="grid grid-cols-1 gap-2 px-4 pt-2">
            {PROFILES.map(p => (
              <button 
                key={p.id} 
                onClick={() => setActiveProfile(p.id)}
                className={`flex items-center gap-3 px-4 py-2.5 rounded-xl text-xs border transition-all ${activeProfile === p.id ? `bg-${p.color}-500/10 border-${p.color}-500/30 text-white` : 'bg-zinc-900 border-white/5 text-zinc-500 hover:bg-zinc-900/50'}`}
              >
                <span>{p.icon}</span>
                <span className="font-bold">{p.name}</span>
              </button>
            ))}
          </div>

          <div className="pt-4 pb-2 text-[10px] font-bold text-zinc-600 uppercase tracking-widest px-4">Neural Config</div>
          <div className="px-4 space-y-4 pt-2">
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-zinc-500 uppercase">Image Size</label>
              <select value={imgSize} onChange={e => setImgSize(e.target.value as any)} className="w-full bg-zinc-900 border border-white/5 rounded-lg p-2 text-xs outline-none">
                <option value="1K">Standard 1K</option>
                <option value="2K">Enhanced 2K</option>
                <option value="4K">Lossless 4K</option>
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-zinc-500 uppercase">Aspect Ratio</label>
              <select value={aspectRatio} onChange={e => setAspectRatio(e.target.value)} className="w-full bg-zinc-900 border border-white/5 rounded-lg p-2 text-xs outline-none">
                <option value="1:1">1:1 Square</option>
                <option value="16:9">16:9 Cinematic</option>
                <option value="9:16">9:16 Portrait</option>
                <option value="4:3">4:3 TV</option>
                <option value="21:9">21:9 UltraWide</option>
              </select>
            </div>
            <label className="flex items-center justify-between text-xs font-medium text-zinc-400 cursor-pointer">
              Thinking Mode <input type="checkbox" checked={useThinking} onChange={e=>setUseThinking(e.target.checked)} className={`rounded bg-zinc-800 border-white/10 text-${profile.color}-500`}/>
            </label>
          </div>
        </nav>

        <div className="pt-6 border-t border-white/5 space-y-3">
          <button onClick={clearHistory} className="w-full flex items-center gap-3 px-4 py-2 rounded-xl text-zinc-500 hover:text-red-400 hover:bg-red-400/5 transition-all text-xs">
            <Icons.Trash /> Clear Intelligence
          </button>
          <button onClick={handleLiveVoice} className={`w-full p-4 rounded-2xl flex items-center justify-between transition-all group ${isLive?'bg-red-500 text-white shadow-lg shadow-red-500/20':`bg-${profile.color}-600/10 border border-${profile.color}-500/20 text-${profile.color}-400`}`}>
            <span className="text-xs font-bold uppercase tracking-widest">{isLive ? "Active Session" : "Voice Uplink"}</span>
            <Icons.Mic active={isLive} />
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-full relative bg-black">
        {view === 'home' ? (
          <div className="flex-1 overflow-y-auto px-12 py-16 space-y-16 animate-slide-up scrollbar-none">
            <div className="max-w-4xl mx-auto text-center space-y-4">
              <h2 className="text-6xl font-black bg-gradient-to-b from-white to-zinc-700 bg-clip-text text-transparent tracking-tighter">Bio-Intelligence Hub</h2>
              <p className="text-zinc-500 max-w-lg mx-auto text-sm leading-relaxed">System monitoring of metabolic rhythm and autonomous executive operations.</p>
            </div>

            <div className="w-full flex flex-col items-center">
              <TCMOrganClock />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 w-full max-w-4xl mx-auto pb-12">
              <div className="p-8 rounded-[2rem] bg-zinc-900/40 border border-white/5 space-y-4 shadow-xl">
                <div className={`w-12 h-12 rounded-xl bg-${profile.color}-500/10 text-${profile.color}-400 flex items-center justify-center`}><Icons.Clock /></div>
                <h3 className="font-bold">Circadian Sync</h3>
                <p className="text-xs text-zinc-500 leading-relaxed">Restored last monitored biological windows for optimized health decision-making across sessions.</p>
              </div>
              <div className="p-8 rounded-[2rem] bg-zinc-900/40 border border-white/5 space-y-4 shadow-xl">
                <div className={`w-12 h-12 rounded-xl bg-${profile.color}-500/10 text-${profile.color}-400 flex items-center justify-center`}><Icons.Brain /></div>
                <h3 className="font-bold">Autonomous Memory</h3>
                <p className="text-xs text-zinc-500 leading-relaxed">Session state is now persistent. Your configurations and insights are retained across browser restarts.</p>
              </div>
            </div>
          </div>
        ) : (
          <>
            <div className="flex-1 overflow-y-auto p-8 space-y-8 max-w-5xl mx-auto w-full scrollbar-none">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center opacity-20 text-center space-y-6">
                  <div className="w-24 h-24 rounded-[2.5rem] bg-white/5 flex items-center justify-center"><Icons.Database /></div>
                  <div>
                    <p className="text-sm font-bold tracking-widest uppercase">Neural Sequence Idle</p>
                    <p className="text-xs mt-2">Initialize multi-modal protocol or circadian inquiry</p>
                  </div>
                </div>
              )}
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                  <div className={`max-w-[85%] p-6 rounded-[2rem] border ${m.role === 'user' ? `bg-${profile.color}-600/10 border-${profile.color}-500/20 shadow-xl` : 'bg-zinc-900/80 border-white/5 backdrop-blur-md shadow-2xl'}`}>
                    {m.image && <img src={m.image} className="rounded-2xl mb-6 max-w-full shadow-2xl border border-white/10" />}
                    {m.video && <video src={m.video} controls className="rounded-2xl mb-6 max-w-full shadow-2xl border border-white/10" />}
                    {m.audio && (
                      <button 
                        onClick={() => {
                          const ctx = new AudioContext();
                          decodeAudioData(decodeBase64(m.audio!), ctx).then(buf => {
                            const src = ctx.createBufferSource();
                            src.buffer = buf;
                            src.connect(ctx.destination);
                            src.start();
                          });
                        }}
                        className={`flex items-center gap-2 mb-4 px-4 py-2 bg-${profile.color}-500/10 rounded-full text-${profile.color}-400 hover:bg-${profile.color}-500/20 transition-all`}
                      >
                        <Icons.Volume /> <span className="text-[10px] font-bold uppercase">Play Vocal Response</span>
                      </button>
                    )}
                    <p className="text-sm whitespace-pre-wrap leading-relaxed text-zinc-200">{m.text}</p>
                    {m.groundingMetadata?.groundingChunks?.length && (
                      <div className="flex flex-wrap gap-2 mt-6 pt-4 border-t border-white/5">
                        {m.groundingMetadata.groundingChunks.map((c, idx) => (
                          <a key={idx} href={c.web?.uri || c.maps?.uri} target="_blank" rel="noopener noreferrer" className={`inline-flex items-center gap-2 px-4 py-2 bg-white/5 rounded-full text-[10px] font-bold text-${profile.color}-300 hover:bg-white/10 transition-all`}>
                            <Icons.Link /> {c.web?.title || c.maps?.title || "Verification Link"}
                          </a>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              ))}
              {loading && <div className="p-4 bg-zinc-900/50 backdrop-blur-md w-14 h-14 rounded-2xl flex items-center justify-center border border-white/5 shadow-inner"><Icons.Loader /></div>}
            </div>

            <footer className="p-8 bg-gradient-to-t from-black to-transparent">
              <div className="max-w-4xl mx-auto space-y-4">
                {mediaFile && (
                  <div className="flex items-center gap-4 bg-zinc-900/80 p-3 rounded-2xl border border-white/5 animate-slide-up">
                    {mediaFile.type.startsWith('image') ? (
                      <img src={mediaFile.data} className="w-16 h-16 object-cover rounded-xl" />
                    ) : (
                      <div className="w-16 h-16 bg-white/5 rounded-xl flex items-center justify-center"><Icons.Movie /></div>
                    )}
                    <div className="flex-1">
                      <p className="text-xs font-bold text-zinc-200">Media Payload Ready</p>
                      <p className="text-[10px] text-zinc-500 uppercase">{mediaFile.type}</p>
                    </div>
                    <button onClick={()=>setMediaFile(null)} className="p-2 hover:text-red-500 transition-colors">✕</button>
                  </div>
                )}

                <div className={`bg-zinc-900/90 backdrop-blur-2xl border border-white/10 rounded-[2.5rem] p-3 flex items-center gap-3 shadow-2xl focus-within:border-${profile.color}-500/50 transition-all`}>
                  <button onClick={() => fileInputRef.current?.click()} className="w-12 h-12 flex items-center justify-center text-zinc-400 hover:text-white hover:bg-white/5 rounded-2xl transition-all">
                    <Icons.Image />
                  </button>
                  <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*,video/*" />

                  <textarea 
                    className="flex-1 bg-transparent px-2 py-3 text-sm outline-none resize-none max-h-48 scrollbar-none" 
                    placeholder={`${profile.name} Mode Active: Send strategy or circadian query...`} 
                    rows={1} 
                    value={input} 
                    onChange={e=>setInput(e.target.value)} 
                    onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault(); handleSend();}}} 
                  />

                  <button onClick={handleSend} disabled={loading} className={`w-12 h-12 flex items-center justify-center rounded-2xl transition-all shadow-lg active:scale-95 ${loading?'bg-zinc-800 text-zinc-600':`bg-white text-black hover:bg-${profile.color}-500 hover:text-white`}`}>
                    <Icons.Send />
                  </button>
                </div>
              </div>
            </footer>
          </>
        )}
      </main>
    </div>
  );
};

createRoot(document.getElementById("root")!).render(<App />);

import React, { useState, useEffect, useRef } from "react";
import { createRoot } from "react-dom/client";
import { GoogleGenAI, Tool, Modality, LiveServerMessage, Type, GenerateContentResponse } from "@google/genai";

// --- Types & Interfaces ---
type Role = "user" | "model";
type ViewState = "home" | "studio" | "assistant";
type ProfileType = "cos" | "shaman" | "architect";

interface Profile {
  id: ProfileType;
  name: string;
  instruction: string;
  color: string;
  icon: string;
}

interface GroundingMetadata {
  groundingChunks?: Array<{
    web?: { uri?: string; title?: string };
    maps?: { uri?: string; title?: string };
  }>;
}

interface Message {
  role: Role;
  text: string;
  image?: string;
  video?: string;
  audio?: string;
  isError?: boolean;
  timestamp: number;
  groundingMetadata?: GroundingMetadata | null;
  thinking?: string;
}

interface OrganInfo {
  name: string;
  action: string;
  startHour: number;
  endHour: number;
}

// --- Data ---
const PROFILES: Profile[] = [
  { 
    id: "cos", 
    name: "Chief of Staff", 
    instruction: "You are Shaman AI acting as a high-level Chief of Staff. Focus on strategy, efficiency, and systems.", 
    color: "indigo",
    icon: "💼"
  },
  { 
    id: "shaman", 
