  const [aspectRatio, setAspectRatio] = useState<string>(savedState.aspectRatio || "16:9");
  const [useThinking, setUseThinking] = useState(savedState.useThinking || false);
  const [activeProfile, setActiveProfile] = useState<ProfileType>(savedState.activeProfile || "cos");
  const [isLive, setIsLive] = useState(false);
  const [mediaFile, setMediaFile] = useState<{data: string, type: string} | null>(null);
  const [showSaveIndicator, setShowSaveIndicator] = useState(false);

  const liveSessionRef = useRef<any>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const profile = PROFILES.find(p => p.id === activeProfile) || PROFILES[0];

  // Persistence side-effect
  useEffect(() => {
    localStorage.setItem('shaman_ai_state', JSON.stringify({
      view,
      messages,
      imgSize,
      aspectRatio,
      useThinking,
      activeProfile
    }));
    setShowSaveIndicator(true);
    const timeout = setTimeout(() => setShowSaveIndicator(false), 2000);
    return () => clearTimeout(timeout);
  }, [view, messages, imgSize, aspectRatio, useThinking, activeProfile]);

  const clearHistory = () => {
    if (confirm("Clear session intelligence? This action cannot be undone.")) {
      setMessages([]);
      localStorage.removeItem('shaman_ai_state');
      window.location.reload();
    }
  };

  const checkKey = async () => {
    if (!(await (window as any).aistudio.hasSelectedApiKey())) {
      await (window as any).aistudio.openSelectKey();
    }
  };

  const handleLiveVoice = async () => {
    if (isLive) {
      liveSessionRef.current?.close();
      setIsLive(false);
      return;
    }
    await checkKey();
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const outputNode = audioCtxRef.current.createGain();
    outputNode.connect(audioCtxRef.current.destination);

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
        systemInstruction: profile.instruction
      },
      callbacks: {
        onmessage: async (msg: LiveServerMessage) => {
          const base64 = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64 && audioCtxRef.current) {
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, audioCtxRef.current.currentTime);
            const buffer = await decodeAudioData(decodeBase64(base64), audioCtxRef.current);
            const source = audioCtxRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(outputNode);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += buffer.duration;
          }
        },
        onclose: () => setIsLive(false),
        onerror: () => setIsLive(false)
      }
    });

    const session = await sessionPromise;
    liveSessionRef.current = session;
    setIsLive(true);

    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    const inputCtx = new AudioContext({ sampleRate: 16000 });
    const source = inputCtx.createMediaStreamSource(stream);
    const processor = inputCtx.createScriptProcessor(4096, 1, 1);
    processor.onaudioprocess = (e) => {
      const data = e.inputBuffer.getChannelData(0);
      const int16 = new Int16Array(data.length);
      for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
      sessionPromise.then(s => s.sendRealtimeInput({ media: { data: encodeBase64(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' } }));
    };
    source.connect(processor);
    processor.connect(inputCtx.destination);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      setMediaFile({
        data: ev.target?.result as string,
        type: file.type
      });
    };
    reader.readAsDataURL(file);
  };

  const handleSend = async () => {
    if (!input.trim() && !mediaFile) return;
    const userPrompt = input;
    const attachedMedia = mediaFile;
    setInput("");
    setMediaFile(null);
    setLoading(true);

    const userMsg: Message = { role: "user", text: userPrompt, timestamp: Date.now() };
    if (attachedMedia?.type.startsWith('image')) userMsg.image = attachedMedia.data;
    if (attachedMedia?.type.startsWith('video')) userMsg.video = attachedMedia.data;
    setMessages(prev => [...prev, userMsg]);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const lcPrompt = userPrompt.toLowerCase();

      if (lcPrompt.includes("generate video") || (lcPrompt.includes("animate") && attachedMedia)) {
        await checkKey();
        const freshAi = new GoogleGenAI({ apiKey: process.env.API_KEY });
        let config: any = { resolution: '720p', aspectRatio: aspectRatio as any };
        let payload: any = { model: 'veo-3.1-fast-generate-preview', prompt: userPrompt, config };

        if (attachedMedia?.type.startsWith('image')) {
          payload.image = { imageBytes: attachedMedia.data.split(',')[1], mimeType: attachedMedia.type };
        }

        let op = await freshAi.models.generateVideos(payload);
        while (!op.done) {
          await new Promise(r => setTimeout(r, 10000));
          op = await freshAi.operations.getVideosOperation({ operation: op });
        }
        const uri = op.response?.generatedVideos?.[0]?.video?.uri;
        const resp = await fetch(`${uri}&key=${process.env.API_KEY}`);
        const blob = await resp.blob();
        setMessages(prev => [...prev, { role: "model", text: "Synthesis complete.", video: URL.createObjectURL(blob), timestamp: Date.now() }]);
      }

      else if (lcPrompt.includes("generate image") || lcPrompt.includes("create image")) {
        await checkKey();
        const freshAi = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const resp = await freshAi.models.generateContent({
          model: 'gemini-3-pro-image-preview',
          contents: { parts: [{ text: userPrompt }] },
          config: { imageConfig: { aspectRatio: aspectRatio as any, imageSize: imgSize as any } }
        });
        const imgPart = resp.candidates[0].content.parts.find(p => p.inlineData);
        if (imgPart) {
          setMessages(prev => [...prev, { role: "model", text: "Generated artifact.", image: `data:image/png;base64,${imgPart.inlineData.data}`, timestamp: Date.now() }]);
        }
      }

      else if (attachedMedia?.type.startsWith('image') && (lcPrompt.includes("filter") || lcPrompt.includes("edit") || lcPrompt.includes("add") || lcPrompt.includes("remove"))) {
        const resp = await ai.models.generateContent({
          model: 'gemini-2.5-flash-image',
          contents: {
            parts: [
              { inlineData: { data: attachedMedia.data.split(',')[1], mimeType: attachedMedia.type } },
              { text: userPrompt }
            ]
          }
        });
        const editedPart = resp.candidates[0].content.parts.find(p => p.inlineData);
        if (editedPart) {
          setMessages(prev => [...prev, { role: "model", text: "Refined output.", image: `data:image/png;base64,${editedPart.inlineData.data}`, timestamp: Date.now() }]);
        }
      }

      else if (lcPrompt.startsWith("say ") || lcPrompt.startsWith("speak ")) {
        const resp = await ai.models.generateContent({
          model: "gemini-2.5-flash-preview-tts",
          contents: [{ parts: [{ text: userPrompt.replace(/^(say|speak)\s+/i, "") }] }],
          config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }
          }
        });
        const audioData = resp.candidates[0].content.parts[0].inlineData?.data;
        if (audioData) {
          setMessages(prev => [...prev, { role: "model", text: "Vocalized response.", audio: audioData, timestamp: Date.now() }]);
        }
      }

      else {
        const parts: any[] = [{ text: userPrompt }];
        if (attachedMedia) {
          parts.push({ inlineData: { data: attachedMedia.data.split(',')[1], mimeType: attachedMedia.type } });
        }

        const config: any = {
          tools: [{ googleSearch: {} }],
          systemInstruction: profile.instruction,
          thinkingConfig: useThinking ? { thinkingBudget: 32768 } : undefined
        };

        const model = useThinking ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
        const stream = await ai.models.generateContentStream({ model, contents: { parts }, config });

        let fullText = "";
        let meta: GroundingMetadata | null = null;
        setMessages(prev => [...prev, { role: "model", text: "", timestamp: Date.now() }]);

        for await (const chunk of stream) {
          const c = chunk as GenerateContentResponse;
          fullText += c.text || "";
          if (c.candidates?.[0]?.groundingMetadata) meta = c.candidates[0].groundingMetadata;
          setMessages(prev => {
            const copy = [...prev];
            copy[copy.length - 1] = { ...copy[copy.length - 1], text: fullText, groundingMetadata: meta };
            return copy;
          });
        }
      }
    } catch (e: any) {
      setMessages(prev => [...prev, { role: "model", text: `Protocol Error: ${e.message}`, isError: true, timestamp: Date.now() }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`flex h-screen bg-black text-zinc-100 font-sans overflow-hidden transition-all duration-700`}>
      <aside className="w-80 bg-zinc-950 border-r border-white/5 flex flex-col p-6 space-y-8 z-30">
