            <Icons.Trash /> Wipe session state
          </button>
          <button onClick={handleLiveVoice} className={`w-full p-4 rounded-2xl flex items-center justify-between transition-all group ${isLive?'bg-red-500 text-white shadow-lg shadow-red-500/20':`bg-${profile.color}-600/10 border border-${profile.color}-500/20 text-${profile.color}-400`}`}>
            <span className="text-xs font-bold uppercase tracking-widest">{isLive ? "Active Session" : "Voice Uplink"}</span>
            <Icons.Mic active={isLive} />
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-full relative bg-black transition-all duration-700">
        {view === 'home' ? (
          <div className="flex-1 overflow-y-auto px-12 py-16 space-y-16 animate-slide-up scrollbar-none">
            <div className="max-w-4xl mx-auto text-center space-y-4">
              <h2 className="text-6xl font-black bg-gradient-to-b from-white to-zinc-700 bg-clip-text text-transparent tracking-tighter">Bio-Intelligence Hub</h2>
              <p className="text-zinc-500 max-w-lg mx-auto text-sm leading-relaxed">System state recovered. Monitoring metabolic rhythm and autonomous executive operations.</p>
            </div>

            <div className="w-full flex flex-col items-center">
              <TCMOrganClock />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 w-full max-w-4xl mx-auto pb-12">
              <div className={`p-8 rounded-[2rem] bg-zinc-900/40 border border-white/5 space-y-4 shadow-xl transition-all hover:border-${profile.color}-500/30`}>
                <div className={`w-12 h-12 rounded-xl bg-${profile.color}-500/10 text-${profile.color}-400 flex items-center justify-center`}><Icons.Clock /></div>
                <h3 className="font-bold">Circadian Sync</h3>
                <p className="text-xs text-zinc-500 leading-relaxed">Last monitored biological window: {ORGAN_CLOCK_DATA[new Date().getHours() >= 23 || new Date().getHours() < 1 ? 0 : Math.floor(new Date().getHours()/2) + 1]?.name || 'Resting'}.</p>
              </div>
              <div className={`p-8 rounded-[2rem] bg-zinc-900/40 border border-white/5 space-y-4 shadow-xl transition-all hover:border-${profile.color}-500/30`}>
                <div className={`w-12 h-12 rounded-xl bg-${profile.color}-500/10 text-${profile.color}-400 flex items-center justify-center`}><Icons.Database /></div>
                <h3 className="font-bold">Session Memory</h3>
                <p className="text-xs text-zinc-500 leading-relaxed">State is persistent. Your {messages.length} messages and active configurations are retained locally.</p>
              </div>
            </div>
          </div>
        ) : (
          <>
            <div className="flex-1 overflow-y-auto p-8 space-y-8 max-w-5xl mx-auto w-full scrollbar-none">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center opacity-20 text-center space-y-6">
                  <div className="w-24 h-24 rounded-[2.5rem] bg-white/5 flex items-center justify-center"><Icons.Database /></div>
                  <div>
                    <p className="text-sm font-bold tracking-widest uppercase">Neural Sequence Idle</p>
                    <p className="text-xs mt-2">Initialize multi-modal protocol or circadian inquiry</p>
                  </div>
                </div>
              )}
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                  <div className={`max-w-[85%] p-6 rounded-[2rem] border ${m.role === 'user' ? `bg-${profile.color}-600/10 border-${profile.color}-500/20 shadow-xl` : 'bg-zinc-900/80 border-white/5 backdrop-blur-md shadow-2xl'}`}>
                    {m.image && <img src={m.image} className="rounded-2xl mb-6 max-w-full shadow-2xl border border-white/10" />}
                    {m.video && <video src={m.video} controls className="rounded-2xl mb-6 max-w-full shadow-2xl border border-white/10" />}
                    {m.audio && (
                      <button 
                        onClick={() => {
                          const ctx = new AudioContext();
                          decodeAudioData(decodeBase64(m.audio!), ctx).then(buf => {
                            const src = ctx.createBufferSource();
                            src.buffer = buf;
                            src.connect(ctx.destination);
                            src.start();
                          });
                        }}
                        className={`flex items-center gap-2 mb-4 px-4 py-2 bg-${profile.color}-500/10 rounded-full text-${profile.color}-400 hover:bg-${profile.color}-500/20 transition-all`}
                      >
                        <Icons.Volume /> <span className="text-[10px] font-bold uppercase">Play Vocal Response</span>
                      </button>
                    )}
                    <p className="text-sm whitespace-pre-wrap leading-relaxed text-zinc-200">{m.text}</p>
                    {m.groundingMetadata?.groundingChunks?.length && (
                      <div className="flex flex-wrap gap-2 mt-6 pt-4 border-t border-white/5">
                        {m.groundingMetadata.groundingChunks.map((c, idx) => (
                          <a key={idx} href={c.web?.uri || c.maps?.uri} target="_blank" rel="noopener noreferrer" className={`inline-flex items-center gap-2 px-4 py-2 bg-white/5 rounded-full text-[10px] font-bold text-${profile.color}-300 hover:bg-white/10 transition-all`}>
                            <Icons.Link /> {c.web?.title || c.maps?.title || "Verification Link"}
                          </a>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              ))}
              {loading && <div className="p-4 bg-zinc-900/50 backdrop-blur-md w-14 h-14 rounded-2xl flex items-center justify-center border border-white/5 shadow-inner"><Icons.Loader /></div>}
            </div>

            <footer className="p-8 bg-gradient-to-t from-black to-transparent">
              <div className="max-w-4xl mx-auto space-y-4">
                {mediaFile && (
                  <div className="flex items-center gap-4 bg-zinc-900/80 p-3 rounded-2xl border border-white/5 animate-slide-up">
                    {mediaFile.type.startsWith('image') ? (
                      <img src={mediaFile.data} className="w-16 h-16 object-cover rounded-xl" />
                    ) : (
                      <div className="w-16 h-16 bg-white/5 rounded-xl flex items-center justify-center"><Icons.Movie /></div>
                    )}
                    <div className="flex-1">
                      <p className="text-xs font-bold text-zinc-200">Media Payload Ready</p>
                      <p className="text-[10px] text-zinc-500 uppercase">{mediaFile.type}</p>
                    </div>
                    <button onClick={()=>setMediaFile(null)} className="p-2 hover:text-red-500 transition-colors">✕</button>
                  </div>
                )}

                <div className={`bg-zinc-900/90 backdrop-blur-2xl border border-white/10 rounded-[2.5rem] p-3 flex items-center gap-3 shadow-2xl focus-within:border-${profile.color}-500/50 transition-all`}>
                  <button onClick={() => fileInputRef.current?.click()} className="w-12 h-12 flex items-center justify-center text-zinc-400 hover:text-white hover:bg-white/5 rounded-2xl transition-all">
                    <Icons.Image />
                  </button>
                  <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*,video/*" />

                  <textarea 
                    className="flex-1 bg-transparent px-2 py-3 text-sm outline-none resize-none max-h-48 scrollbar-none" 
                    placeholder={`${profile.name} Mode Active: Send strategy or circadian query...`} 
                    rows={1} 
                    value={input} 
                    onChange={e=>setInput(e.target.value)} 
                    onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault(); handleSend();}}} 
                  />

                  <button onClick={handleSend} disabled={loading} className={`w-12 h-12 flex items-center justify-center rounded-2xl transition-all shadow-lg active:scale-95 ${loading?'bg-zinc-800 text-zinc-600':`bg-white text-black hover:bg-${profile.color}-500 hover:text-white`}`}>
                    <Icons.Send />
                  </button>
                </div>
              </div>
            </footer>
          </>
        )}
      </main>
    </div>
  );
};

createRoot(document.getElementById("root")!).render(<App />);
